insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('d9000000-0000-0000-0000-000000000001', 'mrcp2', '6cf043db-4f90-4c45-8fed-2d3df9276f53',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('d9000000-0000-0000-0000-000000000001', 'A', 'Give dexamethasone only after 4 days of antibiotics to avoid masking the clinical response', false, 'Ruled out because delaying dexamethasone until after antibiotics have been established loses its mortality/morbidity benefit; the benefit is time-critical and tied to co-administration with the first dose.', 1),
('d9000000-0000-0000-0000-000000000001', 'B', 'Withhold dexamethasone because the purpuric rash suggests meningococcal disease instead', false, 'Ruled out because the Gram stain here already demonstrates Gram-positive diplococci consistent with pneumococcus, and a purpuric rash alone does not exclude pneumococcal disease or negate the indication for dexamethasone.', 2),
('d9000000-0000-0000-0000-000000000001', 'C', 'Delay both antibiotics and dexamethasone until a CT head has been performed', false, 'Ruled out because antibiotics (and dexamethasone) should not be delayed for neuroimaging in suspected bacterial meningitis unless there are specific contraindications to lumbar puncture; delay increases mortality.', 3),
('d9000000-0000-0000-0000-000000000001', 'D', 'Give IV dexamethasone with or just before the first dose of antibiotics', true, 'Correct. Adjunctive dexamethasone reduces mortality and neurological sequelae in pneumococcal meningitis specifically when given with or shortly before the first antibiotic dose; it should be started empirically while awaiting organism confirmation.', 4),
('d9000000-0000-0000-0000-000000000001', 'E', 'Give dexamethasone 12 hours after starting antibiotics once cultures confirm pneumococcus', false, 'Ruled out because dexamethasone given after antibiotics have already been established does not provide the same mortality/morbidity benefit as when given with or before the first dose.', 5),
('d9000000-0000-0000-0000-000000000002', 'A', 'Relapse of HSV encephalitis; restart aciclovir for a further prolonged course', false, 'Ruled out because the repeat CSF HSV PCR is negative, arguing against true viral relapse; the clinical pattern (behavioural change plus dyskinesias) is typical of the secondary autoimmune process rather than recurrent viral replication.', 1),
('d9000000-0000-0000-0000-000000000002', 'B', 'Post-HSV anti-NMDA receptor encephalitis; test CSF for NMDAR antibodies and consider immunotherapy', true, 'Correct. A relapsing neuropsychiatric illness with movement disorder features weeks after treated HSV encephalitis, with a negative repeat HSV PCR, is characteristic of post-HSV anti-NMDA receptor encephalitis, an immune-mediated process requiring antibody testing and immunotherapy rather than further antivirals.', 2),
('d9000000-0000-0000-0000-000000000002', 'C', 'Herpes simplex virus resistance to aciclovir; switch to foscarnet', false, 'Ruled out because there is no evidence of ongoing viral replication (PCR negative) to suggest resistant virus requiring a change in antiviral agent.', 3),
('d9000000-0000-0000-0000-000000000002', 'D', 'Cytomegalovirus reactivation encephalitis; start ganciclovir', false, 'Ruled out because there is no supporting evidence of CMV infection here, and the clinical scenario (temporal relationship to treated HSV encephalitis, orofacial dyskinesias) is classic for post-HSV autoimmune encephalitis, not CMV.', 4),
('d9000000-0000-0000-0000-000000000002', 'E', 'Non-convulsive status epilepticus secondary to prior HSV-related brain injury; arrange urgent EEG and treat with antiepileptics alone', false, 'Ruled out because although EEG may be a reasonable adjunct investigation, the orofacial dyskinesias and behavioural change point toward an autoimmune movement disorder/encephalitis rather than a purely epileptic phenomenon, and antibody testing/immunotherapy should not be omitted.', 5),
('d9000000-0000-0000-0000-000000000003', 'A', 'Continue anti-tuberculous therapy and ART, and increase or restart corticosteroids to manage TB-associated IRIS', true, 'Correct. Paradoxical worsening of TB lesions/neurological signs after starting ART, despite adequate anti-tuberculous treatment and no resistance, indicates TB-associated immune reconstitution inflammatory syndrome; management is corticosteroids while continuing effective anti-tuberculous therapy and ART.', 1),
('d9000000-0000-0000-0000-000000000003', 'B', 'Stop ART immediately and switch to a second-line anti-tuberculous regimen, suspecting drug resistance', false, 'Ruled out because drug levels are adequate and there is no evidence of resistance; the clinical pattern (worsening shortly after ART initiation) is typical of IRIS rather than treatment failure.', 2),
('d9000000-0000-0000-0000-000000000003', 'C', 'Stop anti-tuberculous therapy as it appears ineffective, and pursue surgical resection of the tuberculomas', false, 'Ruled out because anti-tuberculous therapy is working biochemically/microbiologically; the worsening reflects an immune-mediated reaction, not drug failure requiring cessation or primary surgical management.', 3),
('d9000000-0000-0000-0000-000000000003', 'D', 'Continue all current management completely unchanged and reassure the patient', false, 'Ruled out because untreated CNS TB-IRIS can cause life-threatening mass effect or hydrocephalus, and corticosteroid escalation is indicated rather than no change.', 4),
('d9000000-0000-0000-0000-000000000003', 'E', 'Delay restarting ART until the full course of anti-tuberculous therapy is complete', false, 'Ruled out because ART has already been appropriately started after an initial delay; the issue now is managing the resulting IRIS, not further deferring ART.', 5),
('d9000000-0000-0000-0000-000000000004', 'A', 'Start ART immediately alongside antifungal therapy to control HIV as early as possible', false, 'Ruled out because early ART initiation in HIV-associated cryptococcal meningitis increases the risk of cryptococcal immune reconstitution inflammatory syndrome and worse outcomes; ART should be deferred for several weeks.', 1),
('d9000000-0000-0000-0000-000000000004', 'B', 'Insert a ventriculoperitoneal shunt immediately as the first-line pressure management', false, 'Ruled out because therapeutic lumbar puncture is the first-line approach to raised pressure in cryptococcal meningitis in the absence of hydrocephalus refractory to repeated LPs; shunting is reserved for persistent cases.', 2),
('d9000000-0000-0000-0000-000000000004', 'C', 'Avoid lumbar puncture altogether because of the risk of herniation', false, 'Ruled out because, in the absence of a focal mass lesion or midline shift on imaging, therapeutic lumbar puncture is safe and is the recommended first-line method of controlling raised pressure in this condition.', 3),
('d9000000-0000-0000-0000-000000000004', 'D', 'Give oral acetazolamide as the primary means of controlling raised intracranial pressure', false, 'Ruled out because acetazolamide is not recommended for managing raised intracranial pressure in cryptococcal meningitis and has been associated with harm in this setting.', 4),
('d9000000-0000-0000-0000-000000000004', 'E', 'Perform therapeutic serial lumbar punctures aiming for a substantial reduction in opening pressure, and defer ART for approximately 4-6 weeks', true, 'Correct. Raised intracranial pressure is a major cause of morbidity/mortality in cryptococcal meningitis and is managed with therapeutic serial lumbar punctures; ART is deferred for roughly 4-6 weeks after starting antifungal therapy to reduce the risk of cryptococcal IRIS.', 5),
('d9000000-0000-0000-0000-000000000005', 'A', 'IV ceftriaxone alone, as it provides adequate broad empirical CNS coverage', false, 'Ruled out because ceftriaxone (and other cephalosporins) has no reliable activity against Listeria monocytogenes, an important pathogen in older or immunosuppressed patients.', 1),
('d9000000-0000-0000-0000-000000000005', 'B', 'IV vancomycin plus ceftriaxone, without adding ampicillin', false, 'Ruled out because neither vancomycin nor ceftriaxone reliably covers Listeria; ampicillin (or amoxicillin) must be added when this organism is a possibility.', 2),
('d9000000-0000-0000-0000-000000000005', 'C', 'IV amoxicillin (or ampicillin) plus gentamicin, because third-generation cephalosporins do not reliably cover Listeria', true, 'Correct. Listeria monocytogenes is intrinsically resistant to cephalosporins, which otherwise form the backbone of empirical bacterial meningitis cover; ampicillin/amoxicillin plus gentamicin (for synergy) is the standard regimen when Listeria is a possibility, such as in older or immunosuppressed patients.', 3),
('d9000000-0000-0000-0000-000000000005', 'D', 'IV meropenem monotherapy', false, 'Ruled out because although meropenem has some activity against Listeria, it is not the standard first-line empirical regimen; ampicillin plus gentamicin remains the preferred combination.', 4),
('d9000000-0000-0000-0000-000000000005', 'E', 'Oral co-trimoxazole as first-line empirical therapy', false, 'Ruled out because co-trimoxazole is reserved as an alternative for patients with severe penicillin allergy, not as first-line empirical therapy.', 5),
('d9000000-0000-0000-0000-000000000006', 'A', 'Stop antibiotics once the patient is afebrile and clinically improved, usually within 5-7 days', false, 'Ruled out because such a short course is inadequate for brain abscess, which requires a much longer treatment duration to prevent relapse.', 1),
('d9000000-0000-0000-0000-000000000006', 'B', 'No further antibiotics are required, as source control by aspiration alone is curative', false, 'Ruled out because aspiration provides source control but does not replace the need for a prolonged course of targeted antibiotics.', 2),
('d9000000-0000-0000-0000-000000000006', 'C', 'Switch to oral antibiotics immediately after aspiration regardless of lesion size or clinical response', false, 'Ruled out because the switch to oral therapy should be guided by clinical and radiological response over a period of weeks, not made immediately after the procedure.', 3),
('d9000000-0000-0000-0000-000000000006', 'D', 'Continue prolonged IV antibiotics (typically 4-6 weeks) tailored to culture results, with serial imaging to confirm resolution before considering an oral switch', true, 'Correct. Bacterial brain abscess management combines source control (aspiration or excision) with prolonged antibiotic therapy, typically around 4-6 weeks IV, guided by the organism identified and by clinical/radiological response, before any switch to oral therapy.', 4),
('d9000000-0000-0000-0000-000000000006', 'E', 'Repeat aspiration is mandatory every week regardless of clinical response', false, 'Ruled out because repeat aspiration is guided by clinical and radiological response, not performed on a fixed weekly schedule regardless of progress.', 5),
('d9000000-0000-0000-0000-000000000007', 'A', 'Start albendazole alone without steroid cover, since steroids are unnecessary', false, 'Ruled out because antiparasitic therapy without steroid cover risks a significant inflammatory reaction with worsening oedema and seizures as the cysts degenerate.', 1),
('d9000000-0000-0000-0000-000000000007', 'B', 'Start an antiepileptic drug, and if antiparasitic therapy such as albendazole is used, co-administer corticosteroids to control the inflammatory response as cysts degenerate', true, 'Correct. Seizures are the most common presentation of parenchymal neurocysticercosis and require antiepileptic therapy regardless of other decisions. Antiparasitic treatment can provoke an inflammatory reaction as cysts die, worsening oedema and seizures, so corticosteroids are given alongside to mitigate this.', 2),
('d9000000-0000-0000-0000-000000000007', 'C', 'Avoid antiepileptic drugs entirely and treat only with antiparasitic therapy', false, 'Ruled out because antiepileptic therapy is a mainstay of management for seizures in neurocysticercosis, independent of the antiparasitic treatment decision.', 3),
('d9000000-0000-0000-0000-000000000007', 'D', 'Perform emergency neurosurgical excision of all lesions as first-line treatment', false, 'Ruled out because surgery is reserved for specific situations such as intraventricular lesions or large single cysts causing mass effect, not as first-line treatment for typical parenchymal disease.', 4),
('d9000000-0000-0000-0000-000000000007', 'E', 'Withhold all treatment, as the lesions will resolve spontaneously without any intervention', false, 'Ruled out because active, enhancing lesions with ongoing seizures generally warrant antiepileptic (and often antiparasitic with steroid cover) treatment rather than being left untreated.', 5),
('d9000000-0000-0000-0000-000000000008', 'A', 'Proceed to rapid sequence induction of general anaesthesia (e.g. propofol or thiopental) with continuous EEG monitoring and ICU admission', true, 'Correct. Status epilepticus unresponsive to an adequate benzodiazepine dose plus a second-line IV antiepileptic is refractory status epilepticus, requiring escalation to general anaesthesia with continuous EEG monitoring in an intensive care setting.', 1),
('d9000000-0000-0000-0000-000000000008', 'B', 'Give a third benzodiazepine dose and observe further', false, 'Ruled out because two adequate doses of benzodiazepine plus a second-line agent have already failed; further benzodiazepine alone risks respiratory depression without controlling the seizure and delays necessary escalation.', 2),
('d9000000-0000-0000-0000-000000000008', 'C', 'Repeat levetiracetam at a higher loading dose and wait a further 30 minutes before escalating', false, 'Ruled out because the second-line agent has already been given at an appropriate loading dose without effect; further delay before escalating to anaesthesia increases the risk of neuronal injury.', 3),
('d9000000-0000-0000-0000-000000000008', 'D', 'Start oral antiepileptic maintenance therapy and monitor on the ward', false, 'Ruled out because this patient remains in ongoing convulsive status epilepticus and requires urgent escalation of IV treatment in a monitored critical care setting, not oral therapy on a general ward.', 4),
('d9000000-0000-0000-0000-000000000008', 'E', 'Perform emergency EEG only, with no change in pharmacological management', false, 'Ruled out because EEG is a valuable adjunct once anaesthesia is started, but pharmacological escalation itself must not be delayed for investigation alone.', 5),
('d9000000-0000-0000-0000-000000000009', 'A', 'Continue valproate unchanged, as her epilepsy is well controlled and switching risks breakthrough seizures', false, $x$Ruled out because valproate's teratogenic risk in women planning pregnancy is significant enough that specialist review of alternatives is recommended, rather than continuing unchanged without discussion.$x$, 1),
('d9000000-0000-0000-0000-000000000009', 'B', 'Stop all antiepileptic medication immediately given she is planning pregnancy', false, 'Ruled out because abrupt cessation of antiepileptic therapy risks breakthrough seizures, which themselves carry maternal and fetal risk; any change should be gradual and specialist-guided.', 2),
('d9000000-0000-0000-0000-000000000009', 'C', 'Add high-dose folic acid to valproate and continue, since this fully mitigates the teratogenic risk', false, $x$Ruled out because folic acid supplementation is recommended in women with epilepsy planning pregnancy but does not eliminate valproate's specific teratogenic and neurodevelopmental risks.$x$, 3),
('d9000000-0000-0000-0000-000000000009', 'D', 'Switch to phenytoin, considered the safest antiepileptic option in pregnancy', false, 'Ruled out because phenytoin is also associated with teratogenic risk and is not preferred as a lower-risk alternative in this context.', 4),
('d9000000-0000-0000-0000-000000000009', 'E', 'Discuss switching to an alternative antiepileptic with a lower teratogenic risk profile, such as lamotrigine or levetiracetam, under specialist supervision before conception', true, 'Correct. Sodium valproate carries a high risk of major congenital malformations and long-term neurodevelopmental impairment in children exposed in utero. Any switch should be planned and specialist-supervised well before conception, balancing seizure control against teratogenic risk.', 5),
('d9000000-0000-0000-0000-000000000010', 'A', 'Trial a fourth and fifth antiepileptic drug sequentially before considering any referral', false, 'Ruled out because he already meets the definition of drug-resistant epilepsy after failing two adequate drug trials, and further sequential drug trials are unlikely to achieve seizure freedom while delaying potentially curative surgery.', 1),
('d9000000-0000-0000-0000-000000000010', 'B', 'Reassure him that with hippocampal sclerosis, medical therapy will eventually achieve seizure freedom', false, 'Ruled out because hippocampal sclerosis is a classic cause of drug-resistant temporal lobe epilepsy, and medical therapy alone rarely achieves durable seizure freedom in this context.', 2),
('d9000000-0000-0000-0000-000000000010', 'C', 'Refer to a specialist epilepsy surgery centre for pre-surgical evaluation, as he meets criteria for drug-resistant epilepsy', true, 'Correct. Drug-resistant epilepsy is defined as failure of adequate trials of two tolerated, appropriately chosen antiepileptic drug schedules; with a well-localised structural lesion such as hippocampal sclerosis and concordant clinical features, referral for specialist pre-surgical evaluation is appropriate rather than continuing to trial further drugs indefinitely.', 3),
('d9000000-0000-0000-0000-000000000010', 'D', 'Recommend vagal nerve stimulation as first-line, bypassing pre-surgical work-up', false, 'Ruled out because resective surgery evaluation is more appropriate for a well-localised lesion with concordant clinical semiology, offering a substantially higher chance of seizure freedom than neurostimulation.', 4),
('d9000000-0000-0000-0000-000000000010', 'E', 'Discharge him back to primary care for long-term monitoring only', false, 'Ruled out because his drug-resistant, localisable epilepsy warrants specialist referral for surgical evaluation rather than routine primary care follow-up.', 5),
('d9000000-0000-0000-0000-000000000011', 'A', 'His risk of SUDEP is significantly increased by ongoing nocturnal generalised tonic-clonic seizures, and optimising seizure control (including consideration of nocturnal supervision or monitoring) is important in reducing this risk', true, 'Correct. SUDEP risk is strongly associated with frequent, uncontrolled generalised tonic-clonic seizures, particularly nocturnal and unwitnessed ones, and modifiable strategies such as optimising treatment and nocturnal supervision are used to reduce this risk.', 1),
('d9000000-0000-0000-0000-000000000011', 'B', 'SUDEP risk is not affected by seizure frequency or type, so no specific counselling is needed', false, 'Ruled out because SUDEP risk is strongly correlated with the frequency of generalised tonic-clonic seizures, making this an important and modifiable counselling point.', 2),
('d9000000-0000-0000-0000-000000000011', 'C', 'SUDEP only occurs in patients with a structural brain lesion, so this is not relevant to him', false, 'Ruled out because SUDEP is not restricted to patients with structural lesions and is relevant to any patient with poorly controlled generalised tonic-clonic seizures.', 3),
('d9000000-0000-0000-0000-000000000011', 'D', 'He should be reassured that SUDEP is exclusively a paediatric phenomenon', false, 'Ruled out because SUDEP occurs across age groups, including adults, and is not limited to children.', 4),
('d9000000-0000-0000-0000-000000000011', 'E', 'Nothing can be done to modify SUDEP risk, so discussion should be avoided to prevent distress', false, 'Ruled out because several modifiable strategies exist to reduce SUDEP risk, and current practice supports sensitive discussion of this risk with patients and carers rather than avoidance.', 5),
('d9000000-0000-0000-0000-000000000012', 'A', 'The combined oral contraceptive pill is unaffected by carbamazepine and can be continued at the standard dose', false, $x$Ruled out because carbamazepine's enzyme-inducing effect significantly reduces combined oral contraceptive efficacy, increasing the risk of contraceptive failure.$x$, 1),
('d9000000-0000-0000-0000-000000000012', 'B', 'Carbamazepine is a hepatic enzyme inducer that reduces combined oral contraceptive efficacy; advise use of an alternative or additional highly effective method such as a copper IUD, levonorgestrel-releasing IUS, or depot medroxyprogesterone', true, 'Correct. Enzyme-inducing antiepileptic drugs such as carbamazepine reduce the efficacy of hormonal contraceptives metabolised via the same pathway. Non-hormonal or hormonal methods unaffected by enzyme induction, such as the copper IUD, levonorgestrel IUS, or depot medroxyprogesterone, are preferred.', 2),
('d9000000-0000-0000-0000-000000000012', 'C', 'Simply doubling the oestrogen dose of the combined pill fully restores contraceptive efficacy', false, 'Ruled out because dose adjustment of the combined pill is not considered a reliable strategy to overcome the enzyme induction effect of carbamazepine.', 3),
('d9000000-0000-0000-0000-000000000012', 'D', 'Switching to the progestogen-only pill (desogestrel) alone provides fully reliable contraception with carbamazepine', false, 'Ruled out because the efficacy of the progestogen-only pill is also reduced by enzyme-inducing antiepileptics, making it an unreliable choice in this context.', 4),
('d9000000-0000-0000-0000-000000000012', 'E', 'No contraceptive interaction exists with any antiepileptic drug', false, 'Ruled out because several antiepileptic drugs, particularly enzyme inducers, have clinically significant interactions with hormonal contraception.', 5),
('d9000000-0000-0000-0000-000000000013', 'A', 'This represents a new structural lesion, and urgent MRI should be the immediate priority over medication changes', false, 'Ruled out because a new structural lesion is a far less likely explanation than the well-recognised pharmacokinetic change in pregnancy, which should be addressed first.', 1),
('d9000000-0000-0000-0000-000000000013', 'B', 'Lamotrigine should be stopped due to teratogenicity concerns now that she is pregnant', false, 'Ruled out because lamotrigine is generally considered one of the lower-risk antiepileptics in pregnancy, and stopping it would increase the risk of further breakthrough seizures without a clear safety benefit.', 2),
('d9000000-0000-0000-0000-000000000013', 'C', 'The breakthrough seizures are unrelated to pregnancy and no dose change is needed', false, 'Ruled out because pregnancy-related pharmacokinetic changes are a well-recognised and likely explanation here, and dose adjustment is an appropriate response.', 3),
('d9000000-0000-0000-0000-000000000013', 'D', 'Switch immediately to sodium valproate for better seizure control during pregnancy', false, 'Ruled out because valproate carries significant teratogenic risk and is contraindicated as a preferred option in pregnancy.', 4),
('d9000000-0000-0000-0000-000000000013', 'E', 'Pregnancy-related increase in lamotrigine clearance is the likely cause of falling serum levels; check levels where available and increase the dose guided by clinical response', true, 'Correct. Lamotrigine clearance increases substantially during pregnancy due to hormonal induction of glucuronidation, often requiring significant dose increases to maintain seizure control; this is managed by monitoring clinical response (and levels where available) and titrating the dose upward.', 5),
('d9000000-0000-0000-0000-000000000014', 'A', 'Attribute her reduced consciousness solely to a post-ictal state and reassess in 24 hours without further investigation', false, 'Ruled out because this risks missing ongoing non-convulsive status epilepticus, which causes continued neuronal injury if untreated.', 1),
('d9000000-0000-0000-0000-000000000014', 'B', 'Perform lumbar puncture as the immediate priority over EEG', false, 'Ruled out because in this clinical context (recent seizure, subtle ongoing motor signs) urgent EEG to exclude non-convulsive status epilepticus takes priority over lumbar puncture.', 2),
('d9000000-0000-0000-0000-000000000014', 'C', 'Start empirical antibiotics for presumed encephalitis without further neurological assessment', false, 'Ruled out because there is no supporting evidence for infection here, and the priority is excluding ongoing non-convulsive seizure activity given the recent convulsion and subtle motor findings.', 3),
('d9000000-0000-0000-0000-000000000014', 'D', 'Arrange urgent EEG to look for non-convulsive status epilepticus, and treat pharmacologically if confirmed', true, 'Correct. Persistently altered consciousness after a convulsive seizure, especially with subtle motor signs such as eyelid twitching, should raise suspicion for non-convulsive status epilepticus; EEG is essential to confirm this since clinical assessment alone is unreliable, and prompt treatment is required if confirmed.', 4),
('d9000000-0000-0000-0000-000000000014', 'E', 'Discharge home once she is arousable to voice', false, 'Ruled out because discharge would be unsafe without first excluding ongoing non-convulsive status epilepticus in a patient with fluctuating consciousness after a seizure.', 5),
('d9000000-0000-0000-0000-000000000015', 'A', 'Increase the frequency and dose of the triptan to gain better control', false, 'Ruled out because increasing acute medication use, including triptans, worsens medication overuse headache rather than improving control.', 1),
('d9000000-0000-0000-0000-000000000015', 'B', 'Add a second opioid-containing analgesic for breakthrough headache', false, 'Ruled out because opioid-containing analgesics carry a particularly high risk of causing and perpetuating medication overuse headache.', 2),
('d9000000-0000-0000-0000-000000000015', 'C', 'Withdraw the overused acute medications, particularly the opioid-containing combination analgesic, with appropriate support, and consider starting a preventive migraine therapy', true, 'Correct. Medication overuse headache is managed by withdrawing the overused acute medication, which often causes transient worsening before improvement, alongside starting appropriate preventive therapy for the underlying primary headache disorder.', 3),
('d9000000-0000-0000-0000-000000000015', 'D', 'Continue current medications unchanged, as medication overuse headache is not a recognised entity in migraine patients', false, 'Ruled out because medication overuse headache is a well-recognised, clinically important complication of frequent acute headache medication use in patients with a pre-existing headache disorder.', 4),
('d9000000-0000-0000-0000-000000000015', 'E', 'Refer for urgent neuroimaging as the first priority before addressing medication use', false, 'Ruled out because in the absence of red-flag features, addressing medication overuse is the priority rather than urgent imaging.', 5),
('d9000000-0000-0000-0000-000000000016', 'A', 'Start high-dose oral corticosteroids as first-line therapy', false, 'Ruled out because corticosteroids are not first-line therapy for idiopathic intracranial hypertension and can cause weight gain that may worsen the condition.', 1),
('d9000000-0000-0000-0000-000000000016', 'B', 'Proceed directly to optic nerve sheath fenestration without a trial of medical therapy', false, 'Ruled out because medical therapy is first-line unless vision is critically and acutely threatened; surgical options are reserved for medically refractory disease or progressive visual loss.', 2),
('d9000000-0000-0000-0000-000000000016', 'C', 'Reassure that no treatment is required, as the MR venogram is normal', false, 'Ruled out because a normal MR venogram excludes venous sinus thrombosis as a secondary cause but does not mean active treatment is unnecessary; papilloedema and raised pressure still require management to protect vision.', 3),
('d9000000-0000-0000-0000-000000000016', 'D', 'Start acetazolamide, arrange formal visual field assessment, and refer for weight-management support', true, 'Correct. Idiopathic intracranial hypertension is managed primarily with acetazolamide to reduce CSF production, weight loss support, and regular formal visual field and papilloedema monitoring, since visual loss is the main long-term morbidity.', 4),
('d9000000-0000-0000-0000-000000000016', 'E', 'Perform therapeutic lumbar punctures as the mainstay of long-term treatment', false, 'Ruled out because repeated therapeutic lumbar puncture is not a practical long-term strategy and is generally reserved for temporary relief rather than ongoing management.', 5),
('d9000000-0000-0000-0000-000000000017', 'A', 'An oral triptan taken at symptom onset for acute attacks, with amitriptyline for prevention', false, 'Ruled out because oral triptans act too slowly for the short duration of cluster headache attacks, and amitriptyline is not the first-line preventive agent for cluster headache.', 1),
('d9000000-0000-0000-0000-000000000017', 'B', 'Paracetamol and codeine for acute attacks, with propranolol for prevention', false, 'Ruled out because simple/opioid analgesics are not effective for cluster headache attacks, and propranolol is not the established preventive agent for this condition.', 2),
('d9000000-0000-0000-0000-000000000017', 'C', 'High-dose oral corticosteroids alone as both acute and long-term preventive therapy', false, 'Ruled out because corticosteroids may be used for short-term bridging prevention while other preventives are titrated, but are not appropriate as sole acute treatment or long-term prevention.', 3),
('d9000000-0000-0000-0000-000000000017', 'D', 'Sumatriptan taken orally on a daily basis as prophylaxis between attacks', false, 'Ruled out because daily oral triptan use is not standard prophylactic practice in cluster headache; verapamil is the established preventive agent.', 4),
('d9000000-0000-0000-0000-000000000017', 'E', 'High-flow 100% oxygen and a subcutaneous or intranasal triptan for acute attacks, with verapamil (using ECG monitoring for PR interval prolongation) for prevention', true, 'Correct. Acute cluster headache attacks are treated with high-flow oxygen and fast-acting triptan formulations, since oral triptans act too slowly for the short attack duration; verapamil is the first-line preventive agent, requiring ECG monitoring for dose-dependent cardiac conduction effects.', 5),
('d9000000-0000-0000-0000-000000000018', 'A', 'Recommend no further preventive therapy, as three classes have already failed', false, 'Ruled out because further specialist preventive options, including CGRP monoclonal antibodies and onabotulinumtoxinA, exist for chronic migraine refractory to standard oral preventives.', 1),
('d9000000-0000-0000-0000-000000000018', 'B', 'Consider a CGRP-pathway monoclonal antibody, such as erenumab, fremanezumab or galcanezumab, as a further preventive option', true, 'Correct. CGRP-pathway-targeted monoclonal antibodies are an option for chronic migraine prevention after inadequate response to, or intolerance of, an adequate number of standard oral preventive drug classes, as has occurred here.', 2),
('d9000000-0000-0000-0000-000000000018', 'C', 'Trial a fourth conventional oral preventive at maximal tolerated dose before considering biologics', false, 'Ruled out because guidance supports considering biologic therapy after appropriate trials of an adequate number of standard preventives have failed, rather than exhaustively trialling further oral agents indefinitely.', 3),
('d9000000-0000-0000-0000-000000000018', 'D', 'Start onabotulinumtoxinA only after CGRP monoclonal antibodies have also failed', false, 'Ruled out because both botulinum toxin and CGRP monoclonal antibodies are recognised options after standard preventive failure in chronic migraine, and are not required to be sequenced in this strict order.', 4),
('d9000000-0000-0000-0000-000000000018', 'E', 'Refer for detoxification from acute medication as first priority, assuming medication overuse is the cause', false, 'Ruled out because there is no described medication overuse in this patient, so this is not the relevant next step.', 5),
('d9000000-0000-0000-0000-000000000019', 'A', 'Likely migraine with aura; treat with a triptan and discharge', false, 'Ruled out because triptans can precipitate or worsen vasoconstriction in reversible cerebral vasoconstriction syndrome, and the recurrent thunderclap pattern with postpartum onset is atypical for simple migraine.', 1),
('d9000000-0000-0000-0000-000000000019', 'B', 'Reassure that this is a primary exertional headache and no further investigation is needed', false, 'Ruled out because recurrent postpartum thunderclap headaches require vascular imaging to exclude reversible cerebral vasoconstriction syndrome and other secondary causes before being labelled benign.', 2),
('d9000000-0000-0000-0000-000000000019', 'C', 'Reversible cerebral vasoconstriction syndrome; arrange vascular imaging, which may need to be delayed or repeated as vasoconstriction can be absent early, and avoid vasoconstrictive medications including triptans', true, 'Correct. Recurrent exertional thunderclap headaches in the postpartum period, with normal initial CT and CT angiogram, are classic for reversible cerebral vasoconstriction syndrome; vascular imaging may need to be repeated as segmental vasoconstriction can be absent early, and vasoconstrictive drugs such as triptans and ergots should be avoided.', 3),
('d9000000-0000-0000-0000-000000000019', 'D', 'Proceed to lumbar puncture as the definitive next investigation, bypassing vascular imaging', false, 'Ruled out because vascular imaging (repeated or catheter angiography if needed) is the key next step to confirm or exclude reversible cerebral vasoconstriction syndrome given this recurrent, typical pattern.', 4),
('d9000000-0000-0000-0000-000000000019', 'E', 'Start high-dose corticosteroids for presumed CNS vasculitis', false, 'Ruled out because CNS vasculitis is a less likely explanation given the postpartum, exertion-triggered, recurrent thunderclap pattern, and steroids are not standard treatment for reversible cerebral vasoconstriction syndrome.', 5),
('d9000000-0000-0000-0000-000000000020', 'A', 'Arrange MRI brain with attention to the trigeminal nerve root entry zone and posterior fossa, given the bilateral symptoms and treatment resistance, to look for secondary causes such as multiple sclerosis or vascular compression', true, 'Correct. Bilateral involvement and poor response to carbamazepine are red-flag features prompting MRI to exclude secondary causes of trigeminal neuralgia, such as a demyelinating plaque at the trigeminal root entry zone in multiple sclerosis or a compressive vascular loop.', 1),
('d9000000-0000-0000-0000-000000000020', 'B', 'Increase carbamazepine further without imaging, as bilateral trigeminal neuralgia is a typical variant requiring no further workup', false, 'Ruled out because bilateral and treatment-resistant features are atypical and warrant imaging to exclude a secondary cause rather than simply escalating the same drug further.', 2),
('d9000000-0000-0000-0000-000000000020', 'C', 'Switch immediately to microvascular decompression surgery without any imaging', false, 'Ruled out because imaging should be performed first to identify a cause or candidate lesion before considering any surgical intervention.', 3),
('d9000000-0000-0000-0000-000000000020', 'D', 'Diagnose atypical facial pain and refer to chronic pain management only', false, 'Ruled out because the described pain pattern (brief, electric shock-like, trigger-evoked) is classic trigeminal neuralgia, not atypical facial pain, and the change in pattern warrants imaging rather than a change in diagnosis.', 4),
('d9000000-0000-0000-0000-000000000020', 'E', 'Add a course of oral corticosteroids as definitive treatment', false, 'Ruled out because corticosteroids are not a standard or definitive treatment for trigeminal neuralgia.', 5),
('d9000000-0000-0000-0000-000000000021', 'A', 'Withhold corticosteroids until temporal artery biopsy confirms the diagnosis', false, 'Ruled out because delaying treatment pending biopsy risks permanent visual loss, and steroids should be started immediately on clinical suspicion.', 1),
('d9000000-0000-0000-0000-000000000021', 'B', 'Start low-dose aspirin alone and review in one week', false, 'Ruled out because aspirin alone is inadequate; urgent high-dose corticosteroids are required given the visual symptoms.', 2),
('d9000000-0000-0000-0000-000000000021', 'C', 'Arrange outpatient rheumatology referral within 2 weeks without starting treatment', false, 'Ruled out because visual symptoms in giant cell arteritis require same-day treatment, not a delayed outpatient referral.', 3),
('d9000000-0000-0000-0000-000000000021', 'D', 'Perform temporal artery ultrasound as the sole diagnostic step, with no treatment until results are available', false, 'Ruled out because treatment must not await any diagnostic test result once giant cell arteritis with visual symptoms is clinically suspected.', 4),
('d9000000-0000-0000-0000-000000000021', 'E', 'Start high-dose corticosteroids immediately (IV if visual loss is current or evolving), and arrange urgent temporal artery biopsy without delaying treatment', true, 'Correct. Giant cell arteritis with any current or recent visual symptoms constitutes a same-day emergency requiring immediate high-dose corticosteroids to prevent irreversible visual loss; biopsy should be arranged urgently but must never delay treatment.', 5),
('d9000000-0000-0000-0000-000000000022', 'A', 'Increase the interval between levodopa doses to reduce total daily dose', false, 'Ruled out because lengthening the interval between doses would worsen, not improve, the wearing-off phenomenon by leaving longer gaps of inadequate dopaminergic cover.', 1),
('d9000000-0000-0000-0000-000000000022', 'B', 'Switch to a dopamine agonist monotherapy, discontinuing levodopa', false, 'Ruled out because dopamine agonist monotherapy is less effective for established motor symptoms at this stage and is not an appropriate substitute for levodopa here.', 2),
('d9000000-0000-0000-0000-000000000022', 'C', 'Add an anticholinergic agent to manage the wearing-off', false, 'Ruled out because anticholinergics target tremor rather than motor fluctuations, and are poorly tolerated in older patients.', 3),
('d9000000-0000-0000-0000-000000000022', 'D', 'Add a COMT inhibitor (e.g. entacapone) or an MAO-B inhibitor to extend the duration of benefit from each levodopa dose', true, $x$Correct. End-of-dose wearing-off reflects declining striatal dopamine storage capacity as Parkinson's disease progresses; COMT inhibitors and MAO-B inhibitors both reduce levodopa breakdown or extend its effect and are first-line adjuncts for wearing-off.$x$, 4),
('d9000000-0000-0000-0000-000000000022', 'E', 'Refer for deep brain stimulation immediately as first-line management for wearing-off', false, 'Ruled out because medical optimisation, including COMT/MAO-B inhibitor adjuncts, is tried before considering referral for device-based therapy.', 5),
('d9000000-0000-0000-0000-000000000023', 'A', 'Gradually reduce and withdraw the dopamine agonist, replacing lost motor benefit with adjustment of other antiparkinsonian therapy as needed, with psychological support', true, 'Correct. Impulse control disorders are a recognised dose-related adverse effect of dopamine agonists; management is gradual dose reduction and withdrawal, since abrupt cessation can precipitate dopamine agonist withdrawal syndrome, with other antiparkinsonian therapy adjusted to maintain motor control.', 1),
('d9000000-0000-0000-0000-000000000023', 'B', 'Continue ropinirole unchanged, as impulse control disorders are unrelated to dopaminergic medication', false, 'Ruled out because impulse control disorders are a well-recognised adverse effect specifically associated with dopamine agonist therapy.', 2),
('d9000000-0000-0000-0000-000000000023', 'C', 'Add an antipsychotic to suppress the impulsive behaviours while continuing ropinirole', false, 'Ruled out because this does not address the underlying cause and antipsychotics can worsen parkinsonism; the causative agent should be addressed directly.', 3),
('d9000000-0000-0000-0000-000000000023', 'D', 'Immediately stop all antiparkinsonian medication abruptly', false, 'Ruled out because abrupt cessation risks dopamine agonist withdrawal syndrome and severe worsening of motor symptoms; withdrawal should be gradual.', 4),
('d9000000-0000-0000-0000-000000000023', 'E', 'Increase the dose of ropinirole to improve overall symptom control, which will resolve the behavioural change', false, 'Ruled out because increasing the dose of the causative dopamine agonist would be expected to worsen, not resolve, the impulse control disorder.', 5),
('d9000000-0000-0000-0000-000000000024', 'A', 'Increase the total daily levodopa dose to try to override the dyskinesia', false, 'Ruled out because increasing levodopa dose would be expected to worsen peak-dose dyskinesia rather than improve it.', 1),
('d9000000-0000-0000-0000-000000000024', 'B', 'Refer for assessment for deep brain stimulation (typically subthalamic nucleus or globus pallidus interna), as pharmacological options have been exhausted in this well-selected, levodopa-responsive candidate', true, 'Correct. Deep brain stimulation is considered once medically refractory motor fluctuations or dyskinesia significantly impair quality of life, in patients who remain levodopa-responsive without major cognitive or psychiatric contraindications, as pharmacological options (including amantadine) have already failed here.', 2),
('d9000000-0000-0000-0000-000000000024', 'C', 'Discontinue levodopa completely and manage with dopamine agonist monotherapy', false, 'Ruled out because abruptly discontinuing levodopa in an established, levodopa-responsive patient would cause severe worsening of parkinsonism, and dopamine agonist monotherapy is inadequate at this disease stage.', 3),
('d9000000-0000-0000-0000-000000000024', 'D', 'Add an anticholinergic agent specifically to treat the dyskinesia', false, 'Ruled out because anticholinergics are used for tremor, not for levodopa-induced dyskinesia, and are poorly tolerated in this age group.', 4),
('d9000000-0000-0000-0000-000000000024', 'E', 'Advise that no further treatment options exist and management should now be purely supportive or palliative', false, 'Ruled out because deep brain stimulation remains an effective option for well-selected patients with medically refractory motor fluctuations and dyskinesia.', 5),
('d9000000-0000-0000-0000-000000000025', 'A', $x$Idiopathic Parkinson's disease$x$, false, $x$Ruled out because the poor levodopa response, early falls and vertical gaze palsy are atypical for idiopathic Parkinson's disease, which typically shows a good and sustained levodopa response.$x$, 1),
('d9000000-0000-0000-0000-000000000025', 'B', 'Multiple system atrophy, parkinsonian type', false, 'Ruled out because multiple system atrophy classically features early prominent autonomic failure and/or cerebellar signs rather than a vertical supranuclear gaze palsy.', 2),
('d9000000-0000-0000-0000-000000000025', 'C', 'Progressive supranuclear palsy', true, 'Correct. Progressive supranuclear palsy classically presents with early postural instability and falls (often backward), a vertical supranuclear gaze palsy (especially downgaze), axial rigidity, and a poor or transient response to levodopa.', 3),
('d9000000-0000-0000-0000-000000000025', 'D', 'Corticobasal degeneration', false, 'Ruled out because corticobasal degeneration classically features markedly asymmetric limb rigidity, apraxia and alien limb phenomena, rather than the described symmetrical axial pattern with early falls and vertical gaze palsy.', 4),
('d9000000-0000-0000-0000-000000000025', 'E', 'Dementia with Lewy bodies', false, 'Ruled out because the core features of dementia with Lewy bodies are fluctuating cognition, visual hallucinations and REM sleep behaviour disorder, not the described gaze palsy and early falls pattern.', 5),
('d9000000-0000-0000-0000-000000000026', 'A', 'Levodopa/carbidopa', false, $x$Ruled out because essential tremor does not respond to dopaminergic therapy, which helps distinguish it from Parkinson's disease.$x$, 1),
('d9000000-0000-0000-0000-000000000026', 'B', 'Propranolol, or primidone as an alternative first-line agent', true, 'Correct. First-line pharmacological treatments for essential tremor are propranolol and primidone, chosen based on comorbidities and tolerability.', 2),
('d9000000-0000-0000-0000-000000000026', 'C', 'Ropinirole', false, 'Ruled out because dopamine agonists have no established role in the treatment of essential tremor.', 3),
('d9000000-0000-0000-0000-000000000026', 'D', 'Botulinum toxin injections as first-line therapy before any drug trials', false, 'Ruled out because botulinum toxin is reserved for refractory cases after an adequate trial of first-line pharmacological therapy, not used first-line.', 4),
('d9000000-0000-0000-0000-000000000026', 'E', 'Clonazepam as first-line monotherapy', false, 'Ruled out because clonazepam is not a first-line agent for essential tremor; it may be considered as an adjunct or second-line option.', 5),
('d9000000-0000-0000-0000-000000000027', 'A', 'Zinc salts alone as first-line therapy for this newly symptomatic patient with neurological disease', false, 'Ruled out because zinc salts, which reduce intestinal copper absorption, are used more for maintenance therapy or in presymptomatic patients, whereas chelation is preferred first-line to actively remove copper in symptomatic disease.', 1),
('d9000000-0000-0000-0000-000000000027', 'B', 'Oral corticosteroids to reduce hepatic inflammation', false, $x$Ruled out because corticosteroids are not the primary treatment for Wilson's disease, which is a disorder of copper metabolism rather than primary hepatic inflammation.$x$, 2),
('d9000000-0000-0000-0000-000000000027', 'C', 'A copper chelating agent such as penicillamine or trientine, with dietary copper restriction', true, $x$Correct. Chelating agents are first-line for symptomatic Wilson's disease to actively mobilise and excrete excess copper; there is a recognised risk of paradoxical neurological worsening on starting chelation, particularly with penicillamine, requiring careful monitoring.$x$, 3),
('d9000000-0000-0000-0000-000000000027', 'D', 'Liver transplantation as the immediate first-line intervention', false, 'Ruled out because liver transplantation is reserved for fulminant liver failure or treatment-refractory disease, not as an immediate first-line step for this presentation.', 4),
('d9000000-0000-0000-0000-000000000027', 'E', 'Deferoxamine (an iron chelator)', false, $x$Ruled out because deferoxamine chelates iron, not copper, and is the wrong drug class for Wilson's disease.$x$, 5),
('d9000000-0000-0000-0000-000000000028', 'A', 'Levodopa/carbidopa to suppress the chorea', false, 'Ruled out because dopaminergic drugs typically worsen chorea rather than improve it.', 1),
('d9000000-0000-0000-0000-000000000028', 'B', 'An anticholinergic agent such as trihexyphenidyl', false, 'Ruled out because anticholinergics are not indicated for hyperkinetic chorea and have no established role here.', 2),
('d9000000-0000-0000-0000-000000000028', 'C', 'A dopamine agonist such as pramipexole', false, 'Ruled out because dopamine agonists would be expected to worsen chorea, not improve it.', 3),
('d9000000-0000-0000-0000-000000000028', 'D', $x$No pharmacological options exist for chorea in Huntington's disease$x$, false, $x$Ruled out because VMAT2 inhibitors and atypical antipsychotics are established pharmacological options for chorea in Huntington's disease.$x$, 4),
('d9000000-0000-0000-0000-000000000028', 'E', 'A vesicular monoamine transporter type 2 (VMAT2) inhibitor such as tetrabenazine, with attention to depression risk', true, $x$Correct. VMAT2 inhibitors reduce presynaptic dopamine release and are effective for chorea in Huntington's disease, but carry a risk of depression and suicidality requiring monitoring, particularly important given the underlying disease's psychiatric burden.$x$, 5),
('d9000000-0000-0000-0000-000000000029', 'A', 'Start a disease-modifying therapy immediately as the primary treatment for the acute relapse', false, 'Ruled out because disease-modifying therapies act to reduce future relapse frequency and disability accumulation; they are not used to treat an acute relapse itself.', 1),
('d9000000-0000-0000-0000-000000000029', 'B', 'Plasma exchange as first-line therapy for this relapse', false, 'Ruled out because plasma exchange is reserved for severe relapses that fail to respond adequately to corticosteroids, not as first-line treatment.', 2),
('d9000000-0000-0000-0000-000000000029', 'C', 'Reassure and await spontaneous recovery without any treatment, as steroids provide no benefit', false, 'Ruled out because corticosteroids do hasten recovery from a significant relapse, even though they do not change long-term outcome.', 3),
('d9000000-0000-0000-0000-000000000029', 'D', 'IV (or high-dose oral) methylprednisolone for 3-5 days to hasten recovery from the relapse', true, 'Correct. High-dose corticosteroids are used to hasten recovery from an acute MS relapse causing significant functional impairment, though they do not alter the long-term disease trajectory.', 4),
('d9000000-0000-0000-0000-000000000029', 'E', 'Long-term oral prednisolone maintenance therapy', false, 'Ruled out because short pulsed courses of high-dose steroids are used for relapses, not long-term maintenance therapy.', 5),
('d9000000-0000-0000-0000-000000000030', 'A', 'Continue periodic JC virus antibody testing during treatment, as seroconversion increases the risk of progressive multifocal leukoencephalopathy', true, 'Correct. Natalizumab carries a risk of progressive multifocal leukoencephalopathy caused by JC virus reactivation; risk stratification depends partly on JC virus antibody status, and JC virus antibody-negative patients can still seroconvert during treatment, so periodic retesting is required.', 1),
('d9000000-0000-0000-0000-000000000030', 'B', 'No ongoing monitoring is required once a baseline JC virus antibody test is negative, as risk remains permanently zero', false, 'Ruled out because seroconversion can occur during treatment, meaning a negative baseline test does not guarantee ongoing zero risk, and periodic retesting is required.', 2),
('d9000000-0000-0000-0000-000000000030', 'C', 'Routine monitoring should focus on renal function as the primary concern with natalizumab', false, 'Ruled out because the principal safety concern with natalizumab is progressive multifocal leukoencephalopathy, not renal function.', 3),
('d9000000-0000-0000-0000-000000000030', 'D', 'Natalizumab has no associated risk of opportunistic CNS infection', false, 'Ruled out because natalizumab carries a well-recognised risk of progressive multifocal leukoencephalopathy, an opportunistic CNS infection caused by JC virus.', 4),
('d9000000-0000-0000-0000-000000000030', 'E', 'Annual liver function tests are the main required monitoring for natalizumab safety', false, 'Ruled out because although liver function may be monitored with some disease-modifying therapies, the key specific safety monitoring for natalizumab is JC virus antibody status in relation to progressive multifocal leukoencephalopathy risk.', 5),
('d9000000-0000-0000-0000-000000000031', 'A', 'Continue interferon beta, as it is equally effective across the demyelinating disease spectrum including NMOSD', false, 'Ruled out because interferon beta can worsen NMOSD and is not an appropriate treatment for this condition.', 1),
('d9000000-0000-0000-0000-000000000031', 'B', 'Switch to natalizumab, which is highly effective and specifically indicated in NMOSD', false, 'Ruled out because natalizumab has also been reported to worsen NMOSD and is not an indicated treatment for this condition.', 2),
('d9000000-0000-0000-0000-000000000031', 'C', 'No disease-modifying treatment is required, as NMOSD typically has a benign monophasic course', false, 'Ruled out because NMOSD is typically a relapsing disease that can cause severe cumulative disability, often worse per attack than MS, and requires ongoing immunosuppressive treatment.', 3),
('d9000000-0000-0000-0000-000000000031', 'D', 'Manage exactly as MS with the same first-line injectable disease-modifying therapies', false, 'Ruled out because NMOSD requires a distinct treatment approach, as several standard MS therapies are ineffective or harmful in this condition.', 4),
('d9000000-0000-0000-0000-000000000031', 'E', 'Stop interferon beta, which can worsen NMOSD, and start an NMOSD-specific immunosuppressive therapy such as rituximab (or another approved agent such as eculizumab, satralizumab, or inebilizumab)', true, 'Correct. Neuromyelitis optica spectrum disorder is a distinct, typically antibody/complement-mediated disease from MS; several classic MS disease-modifying therapies, including interferon beta, can worsen NMOSD and should be stopped, replaced with agents such as rituximab or other NMOSD-specific approved therapies.', 5),
('d9000000-0000-0000-0000-000000000032', 'A', 'Administer the first dose under continuous cardiac monitoring (ECG and hourly observations) for at least 6 hours, watching for bradycardia or atrioventricular block', true, 'Correct. Fingolimod can cause transient bradycardia and atrioventricular conduction block, most pronounced after the first dose, necessitating first-dose cardiac monitoring in a supervised setting.', 1),
('d9000000-0000-0000-0000-000000000032', 'B', 'No specific monitoring is required for the first dose, as fingolimod has no cardiac effects', false, 'Ruled out because first-dose bradyarrhythmia is a well-recognised risk of fingolimod requiring monitoring.', 2),
('d9000000-0000-0000-0000-000000000032', 'C', 'Administer the first dose at home with no monitoring, given his low cardiovascular risk', false, 'Ruled out because first-dose monitoring is required for all patients starting fingolimod, regardless of baseline cardiovascular risk.', 3),
('d9000000-0000-0000-0000-000000000032', 'D', 'Only monitor blood pressure hourly with no ECG required', false, 'Ruled out because ECG monitoring is specifically required to detect conduction abnormalities, not blood pressure monitoring alone.', 4),
('d9000000-0000-0000-0000-000000000032', 'E', 'Monitoring is only required for doses after the first, not the initial dose', false, 'Ruled out because it is specifically the first dose that carries the highest risk of bradycardia and requires supervised monitoring.', 5),
('d9000000-0000-0000-0000-000000000033', 'A', 'Continue natalizumab unchanged indefinitely, as excellent disease control outweighs any risk', false, 'Ruled out because the risk-benefit balance shifts substantially with treatment duration and rising JC virus antibody index, warranting active reassessment rather than unchanged continuation.', 1),
('d9000000-0000-0000-0000-000000000033', 'B', 'Discuss the significantly increased PML risk with prolonged natalizumab exposure and rising JC virus antibody index, and consider switching to an alternative disease-modifying therapy with a different risk profile', true, 'Correct. PML risk with natalizumab rises substantially with treatment duration beyond 2 years and a rising JC virus antibody index; when risk becomes unacceptable, switching to an alternative disease-modifying therapy is considered, balancing this against the risk of disease reactivation.', 2),
('d9000000-0000-0000-0000-000000000033', 'C', 'Stop all disease-modifying therapy immediately with no replacement plan', false, 'Ruled out because abruptly stopping without a replacement plan risks significant disease reactivation, sometimes with rebound activity, after natalizumab cessation.', 3),
('d9000000-0000-0000-0000-000000000033', 'D', 'Increase the natalizumab dosing frequency to improve efficacy further', false, 'Ruled out because increasing dosing frequency is not an appropriate response to rising PML risk and is not relevant here.', 4),
('d9000000-0000-0000-0000-000000000033', 'E', 'Add prophylactic antiviral therapy against JC virus to allow continued natalizumab use', false, 'Ruled out because no effective prophylactic antiviral therapy against JC virus/PML exists.', 5),
('d9000000-0000-0000-0000-000000000034', 'A', 'Relapse risk is unaffected by pregnancy and no specific counselling or planning is needed', false, 'Ruled out because relapse risk changes predictably across pregnancy and the postpartum period, making specific counselling and planning important.', 1),
('d9000000-0000-0000-0000-000000000034', 'B', 'All disease-modifying therapies are safe to continue unchanged throughout pregnancy and breastfeeding with no need for individualised review', false, 'Ruled out because safety profiles differ significantly between disease-modifying therapies in pregnancy and breastfeeding, and individualised review is required.', 2),
('d9000000-0000-0000-0000-000000000034', 'C', 'Relapse rate typically falls during pregnancy, particularly the third trimester, but rises in the postpartum period, so plans for continuing or resuming an appropriate disease-modifying therapy after delivery should be discussed in advance, alongside individualised advice on her specific drug before conception', true, 'Correct. Relapse rates in MS typically decrease during pregnancy, especially the third trimester, but rebound in the first 3-6 months postpartum; decisions about therapy around conception and pregnancy are individualised to the specific drug, ideally planned well in advance.', 3),
('d9000000-0000-0000-0000-000000000034', 'D', 'She should be advised to avoid pregnancy altogether, as pregnancy is generally harmful in MS', false, 'Ruled out because pregnancy is not discouraged in MS and does not worsen long-term prognosis.', 4),
('d9000000-0000-0000-0000-000000000034', 'E', 'Disease-modifying therapy should be stopped immediately with no plan for postpartum resumption given the risk of rebound', false, 'Ruled out because planning ahead for prompt postpartum resumption of therapy is important given the recognised postpartum relapse risk, rather than simply stopping with no plan.', 5),
('d9000000-0000-0000-0000-000000000035', 'A', 'Stop all disease-modifying therapy, as no treatment has any evidence of benefit once secondary progression begins', false, 'Ruled out because agents with evidence specifically in active secondary progressive MS exist and should be considered when ongoing inflammatory activity is present.', 1),
('d9000000-0000-0000-0000-000000000035', 'B', 'Start a first-line injectable (interferon beta or glatiramer acetate) as the most appropriate option specifically for progressive disease', false, 'Ruled out because these agents have better evidence in relapsing disease and are less established for progressive disease, particularly compared with agents with specific progressive-disease evidence.', 2),
('d9000000-0000-0000-0000-000000000035', 'C', 'Recommend high-dose oral corticosteroid maintenance therapy for progression', false, 'Ruled out because chronic corticosteroid maintenance is not an evidence-based approach for progressive MS.', 3),
('d9000000-0000-0000-0000-000000000035', 'D', 'Consider a disease-modifying therapy with evidence in active secondary progressive MS, such as siponimod, or continuing/switching a highly effective therapy, given ongoing relapse/MRI activity superimposed on progression', true, 'Correct. Secondary progressive MS with evidence of ongoing inflammatory activity (relapses, new/enhancing MRI lesions) still has treatment options with proven benefit; siponimod is an example of an agent with specific evidence of benefit in active secondary progressive MS.', 4),
('d9000000-0000-0000-0000-000000000035', 'E', 'Manage only with symptomatic and rehabilitative therapy, as no disease-modifying options exist regardless of ongoing MRI activity', false, 'Ruled out because ongoing inflammatory activity (relapses/enhancing lesions) supports a role for disease-modifying therapy even in secondary progressive MS, distinguishing it from purely symptomatic management.', 5),
('d9000000-0000-0000-0000-000000000036', 'A', 'Increase the dose of oral pyridostigmine as the primary intervention for respiratory failure', false, 'Ruled out because increasing pyridostigmine does not adequately address impending respiratory failure in crisis and risks cholinergic excess.', 1),
('d9000000-0000-0000-0000-000000000036', 'B', 'Urgent transfer to intensive care for close respiratory monitoring and likely ventilatory support, and initiate plasma exchange or IVIG for the myasthenic crisis, while identifying and stopping precipitants such as gentamicin', true, 'Correct. Myasthenic crisis is a medical emergency; declining forced vital capacity is a key marker of impending respiratory failure requiring ICU-level monitoring/support, with plasma exchange or IVIG as acute treatment, and identification/removal of precipitating drugs such as aminoglycosides.', 2),
('d9000000-0000-0000-0000-000000000036', 'C', 'Continue gentamicin as the infection needs treating, and manage the myasthenia symptomatically only', false, 'Ruled out because aminoglycosides impair neuromuscular transmission and worsen myasthenia gravis; the precipitating drug should be stopped and an alternative antibiotic used.', 3),
('d9000000-0000-0000-0000-000000000036', 'D', 'Discharge with close outpatient follow-up once symptoms are noted to fluctuate', false, 'Ruled out because this is unsafe given a declining forced vital capacity indicating impending respiratory failure.', 4),
('d9000000-0000-0000-0000-000000000036', 'E', 'Start high-dose oral corticosteroids alone as sufficient treatment for this acute crisis', false, 'Ruled out because corticosteroids can transiently worsen myasthenia in the first 1-2 weeks and act too slowly for acute crisis management; plasma exchange or IVIG is needed acutely.', 5),
('d9000000-0000-0000-0000-000000000037', 'A', 'Start high-dose corticosteroids as first-line disease-modifying treatment', false, 'Ruled out because corticosteroids have no proven benefit in Guillain-Barre syndrome and are not recommended.', 1),
('d9000000-0000-0000-0000-000000000037', 'B', 'Combine IVIG and plasma exchange simultaneously for maximal benefit', false, 'Ruled out because combination therapy has not shown additional benefit over either treatment alone.', 2),
('d9000000-0000-0000-0000-000000000037', 'C', 'Start IVIG or plasma exchange (equally effective, choice guided by availability and contraindications), with close monitoring of respiratory function and for autonomic instability such as arrhythmia or blood pressure lability', true, 'Correct. IVIG and plasma exchange are equally effective disease-modifying treatments for Guillain-Barre syndrome; close monitoring for respiratory failure (serial vital capacity) and autonomic dysfunction is essential, as these are major causes of morbidity and mortality.', 3),
('d9000000-0000-0000-0000-000000000037', 'D', 'Delay treatment until weakness becomes severe (unable to walk) before starting IVIG or plasma exchange', false, 'Ruled out because treatment should start promptly once the diagnosis is suspected and disease is progressing, particularly with respiratory or bulbar involvement, rather than waiting for maximal severity.', 4),
('d9000000-0000-0000-0000-000000000037', 'E', 'Manage with supportive care alone, as Guillain-Barre syndrome is typically self-limiting without specific treatment', false, 'Ruled out because disease-modifying treatment shortens recovery time and reduces the severity of significant Guillain-Barre syndrome.', 5),
('d9000000-0000-0000-0000-000000000038', 'A', 'No treatment is required, as CIDP typically resolves spontaneously within weeks like Guillain-Barre syndrome', false, 'Ruled out because CIDP is by definition chronic and relapsing (more than 8 weeks), distinguishing it from the acute, self-limiting course of Guillain-Barre syndrome, and usually requires ongoing immunotherapy.', 1),
('d9000000-0000-0000-0000-000000000038', 'B', 'Long-term antiviral therapy, given the likely post-infectious aetiology', false, 'Ruled out because antiviral therapy is not the mechanism or treatment for CIDP, which is an immune-mediated demyelinating polyneuropathy.', 2),
('d9000000-0000-0000-0000-000000000038', 'C', 'Antiepileptic medication as the primary treatment for the sensory symptoms', false, 'Ruled out because antiepileptics do not address the underlying immune-mediated demyelination driving the disease.', 3),
('d9000000-0000-0000-0000-000000000038', 'D', 'IVIG, or alternatively corticosteroids or plasma exchange, given the diagnosis of chronic inflammatory demyelinating polyneuropathy', true, 'Correct. First-line treatments for CIDP include IVIG, corticosteroids, or plasma exchange, often requiring long-term maintenance immunotherapy given the chronic, relapsing course.', 4),
('d9000000-0000-0000-0000-000000000038', 'E', 'Immediate nerve biopsy and surgical decompression', false, 'Ruled out because surgical decompression is not indicated for a diffuse immune-mediated demyelinating polyneuropathy.', 5),
('d9000000-0000-0000-0000-000000000039', 'A', 'Delay non-invasive ventilation until the patient develops daytime respiratory failure with overt hypercapnia', false, 'Ruled out because early initiation of non-invasive ventilation for nocturnal hypoventilation improves survival and quality of life compared with waiting for overt daytime hypercapnic failure.', 1),
('d9000000-0000-0000-0000-000000000039', 'B', 'Insert a PEG tube immediately regardless of current swallowing safety, before any respiratory intervention', false, 'Ruled out because gastrostomy timing is guided by swallowing safety and nutritional status; while early planning discussion is appropriate, immediate insertion is not mandated at this stage when he still swallows safely.', 2),
('d9000000-0000-0000-0000-000000000039', 'C', 'Stop riluzole once respiratory symptoms develop, as it is no longer of benefit', false, 'Ruled out because riluzole modestly prolongs survival and is generally continued throughout the disease course unless intolerable side effects occur.', 3),
('d9000000-0000-0000-0000-000000000039', 'D', 'Recommend invasive mechanical ventilation via tracheostomy as the next appropriate step', false, 'Ruled out because non-invasive ventilation is used first-line for this degree of respiratory insufficiency; invasive ventilation is a much larger decision usually discussed separately and is not the default next step here.', 4),
('d9000000-0000-0000-0000-000000000039', 'E', 'Continue riluzole, initiate non-invasive ventilation for the nocturnal hypoventilation, and proactively discuss and plan for future gastrostomy feeding before swallowing significantly deteriorates', true, 'Correct. Non-invasive ventilation is offered for symptomatic early respiratory insufficiency and has demonstrated survival and quality-of-life benefit when started proactively; gastrostomy planning should begin while swallowing is still safe, as riluzole is continued throughout the disease course.', 5),
('d9000000-0000-0000-0000-000000000040', 'A', '3,4-diaminopyridine to improve neuromuscular transmission, alongside treatment of the underlying malignancy, which often improves the paraneoplastic syndrome', true, 'Correct. 3,4-diaminopyridine enhances presynaptic acetylcholine release and is the mainstay symptomatic treatment for Lambert-Eaton myasthenic syndrome; treating the underlying malignancy is also important, as tumour treatment can improve the neurological syndrome.', 1),
('d9000000-0000-0000-0000-000000000040', 'B', 'Pyridostigmine is the treatment of choice and 3,4-diaminopyridine has no established role', false, 'Ruled out because 3,4-diaminopyridine has a more specific mechanism and stronger evidence base in Lambert-Eaton myasthenic syndrome, though pyridostigmine may sometimes be used as an adjunct.', 2),
('d9000000-0000-0000-0000-000000000040', 'C', 'Plasma exchange has no role even in severe cases', false, 'Ruled out because plasma exchange or IVIG can be used for more severe Lambert-Eaton myasthenic syndrome.', 3),
('d9000000-0000-0000-0000-000000000040', 'D', 'Treatment of the underlying malignancy is irrelevant to the neurological syndrome', false, 'Ruled out because treating the tumour often improves the paraneoplastic neurological syndrome in Lambert-Eaton myasthenic syndrome.', 4),
('d9000000-0000-0000-0000-000000000040', 'E', 'Avoid any treatment of the neuromuscular syndrome until the tumour is fully staged and resected', false, 'Ruled out because symptomatic treatment of the neuromuscular syndrome should not be delayed pending complete oncological staging and resection.', 5),
('d9000000-0000-0000-0000-000000000041', 'A', 'Start IVIG, as this represents an acquired inflammatory demyelinating polyneuropathy', false, 'Ruled out because the uniform demyelinating pattern and hereditary features indicate an inherited neuropathy rather than an acquired inflammatory process such as CIDP, and would not be expected to respond to immunotherapy.', 1),
('d9000000-0000-0000-0000-000000000041', 'B', 'Start high-dose corticosteroids as first-line treatment', false, 'Ruled out because there is no role for immunotherapy in an inherited demyelinating neuropathy.', 2),
('d9000000-0000-0000-0000-000000000041', 'C', 'Arrange genetic testing, such as for PMP22 duplication, the most common cause of CMT type 1A, to confirm the diagnosis, and refer for orthotics/physiotherapy and genetic counselling given the inherited pattern', true, 'Correct. The uniformly slowed demyelinating pattern with a hereditary pattern of pes cavus, absent reflexes, and family history is typical of Charcot-Marie-Tooth disease; genetic testing (PMP22 duplication being the most common cause) confirms the diagnosis, with management focused on supportive measures and genetic counselling.', 3),
('d9000000-0000-0000-0000-000000000041', 'D', 'No further investigation is required beyond clinical diagnosis and reassurance, as no genetic testing is available for hereditary neuropathies', false, 'Ruled out because genetic testing is available and clinically useful for confirming the diagnosis and subtype of hereditary neuropathies such as Charcot-Marie-Tooth disease.', 4),
('d9000000-0000-0000-0000-000000000041', 'E', 'Recommend nerve biopsy as the diagnostic investigation of choice', false, 'Ruled out because genetic testing has largely superseded nerve biopsy for diagnosing hereditary neuropathies.', 5),
('d9000000-0000-0000-0000-000000000042', 'A', 'Pre-operative ECG (and further cardiac assessment as indicated) for cardiac conduction disease, and anaesthetic planning to avoid or minimise depolarising muscle relaxants and other agents that can precipitate severe myotonic reactions or respiratory depression', true, 'Correct. Myotonic dystrophy carries significant anaesthetic risk, including cardiac conduction abnormalities that may be asymptomatic yet life-threatening, and risk of a generalised myotonic reaction to depolarising muscle relaxants such as suxamethonium; pre-operative ECG is important even in asymptomatic patients.', 1),
('d9000000-0000-0000-0000-000000000042', 'B', 'No specific precautions are needed beyond standard pre-operative assessment, as myotonic dystrophy does not affect anaesthetic risk', false, 'Ruled out because myotonic dystrophy carries significant, well-recognised anaesthetic risks requiring specific precautions.', 2),
('d9000000-0000-0000-0000-000000000042', 'C', 'Routine use of suxamethonium is preferred for rapid sequence induction in this patient', false, 'Ruled out because suxamethonium can precipitate a severe generalised myotonic contraction in myotonic dystrophy and should be avoided.', 3),
('d9000000-0000-0000-0000-000000000042', 'D', 'Cardiac assessment is unnecessary as cardiac involvement only occurs in advanced or symptomatic disease', false, 'Ruled out because conduction abnormalities can be present and dangerous even when the patient is asymptomatic, making pre-operative ECG important regardless of symptom severity.', 4),
('d9000000-0000-0000-0000-000000000042', 'E', 'General anaesthesia is absolutely contraindicated and surgery cannot proceed', false, 'Ruled out because surgery can proceed with appropriate precautions and specialist anaesthetic input; general anaesthesia is not absolutely contraindicated.', 5),
('d9000000-0000-0000-0000-000000000043', 'A', 'Withhold thrombolysis, as the exact time of onset is unknown and treatment cannot be given outside a clearly established window under any circumstances', false, 'Ruled out because the DWI-FLAIR mismatch protocol specifically allows thrombolysis to be considered in wake-up strokes when exact onset time is unknown.', 1),
('d9000000-0000-0000-0000-000000000043', 'B', 'Proceed directly to mechanical thrombectomy alone, withholding thrombolysis', false, 'Ruled out because thrombolysis eligibility assessment remains appropriate here if criteria are met; thrombectomy is a separate, additional consideration when a large vessel occlusion is confirmed.', 2),
('d9000000-0000-0000-0000-000000000043', 'C', 'Treat with antiplatelet therapy only, as thrombolysis is never appropriate in wake-up stroke', false, 'Ruled out because thrombolysis can be appropriate in wake-up stroke when supported by DWI-FLAIR mismatch imaging criteria.', 3),
('d9000000-0000-0000-0000-000000000043', 'D', 'Delay any treatment until a repeat MRI in 24 hours confirms lesion evolution', false, 'Ruled out because such a delay would forgo the time-critical benefit of thrombolysis.', 4),
('d9000000-0000-0000-0000-000000000043', 'E', 'Proceed with IV thrombolysis, as DWI-FLAIR mismatch suggests the infarct is likely under 4.5 hours old, supporting thrombolysis eligibility despite the unknown exact onset time', true, 'Correct. In wake-up or unknown-onset stroke, a DWI-positive lesion without a corresponding FLAIR signal change (DWI-FLAIR mismatch) suggests the infarct is recent, typically under 4.5 hours, supporting a trial of IV thrombolysis under specific imaging-based protocols.', 5),
('d9000000-0000-0000-0000-000000000044', 'A', 'Withhold thrombectomy, as intervention beyond 6 hours from onset is never beneficial regardless of imaging findings', false, 'Ruled out because extended-window trials have established benefit from thrombectomy up to 24 hours in patients with favourable perfusion imaging.', 1),
('d9000000-0000-0000-0000-000000000044', 'B', 'Treat with IV thrombolysis alone, as this is both effective and safe this far outside the standard treatment window', false, 'Ruled out because thrombolysis is not indicated this late in this scenario; the primary evidence-based intervention here is thrombectomy given the confirmed large vessel occlusion and favourable perfusion profile.', 2),
('d9000000-0000-0000-0000-000000000044', 'C', 'Manage conservatively with antiplatelet therapy only, given the delayed presentation', false, 'Ruled out because this would forgo a highly effective, evidence-based intervention supported by favourable imaging.', 3),
('d9000000-0000-0000-0000-000000000044', 'D', 'Proceed with mechanical thrombectomy, as extended-window criteria based on favourable perfusion imaging showing a small core with substantial mismatch support intervention up to 24 hours from last known well', true, 'Correct. Mechanical thrombectomy has an extended treatment window, up to 24 hours from last known well, in carefully selected patients with large vessel occlusion and favourable perfusion imaging showing a small infarct core with a large volume of salvageable penumbra.', 4),
('d9000000-0000-0000-0000-000000000044', 'E', $x$Perform thrombectomy only if the patient's NIHSS score is below 6$x$, false, 'Ruled out because extended-window thrombectomy eligibility is based on imaging mismatch/core size criteria specific to trial protocols, not this rule.', 5),
('d9000000-0000-0000-0000-000000000045', 'A', 'Manage with osmotic therapy such as mannitol or hypertonic saline alone, as this is sufficient definitive treatment for malignant MCA infarction with herniation', false, 'Ruled out because medical therapy alone is inadequate for this degree of mass effect; surgery is required to substantially reduce mortality in this setting.', 1),
('d9000000-0000-0000-0000-000000000045', 'B', 'Urgent neurosurgical referral for decompressive hemicraniectomy, given clinical and radiological evidence of malignant MCA syndrome with impending herniation in a suitable candidate', true, 'Correct. Malignant MCA infarction with progressive oedema causing herniation carries very high mortality with medical management alone; decompressive hemicraniectomy significantly reduces mortality and can improve functional outcomes, particularly when performed early after stroke onset.', 2),
('d9000000-0000-0000-0000-000000000045', 'C', 'Await further deterioration before considering surgery, as early intervention has no evidence of benefit', false, 'Ruled out because earlier decompressive surgery, ideally within 48 hours of onset, improves survival and functional outcome compared with delayed intervention.', 3),
('d9000000-0000-0000-0000-000000000045', 'D', 'Manage conservatively with palliative care only, given the severity of the infarct', false, 'Ruled out because decompressive hemicraniectomy can be life-saving and is appropriate for a previously independent patient with malignant MCA syndrome and evolving herniation.', 4),
('d9000000-0000-0000-0000-000000000045', 'E', 'Perform therapeutic hypothermia as the definitive treatment instead of surgery', false, 'Ruled out because therapeutic hypothermia is not an established effective alternative to surgical decompression in this context.', 5),
('d9000000-0000-0000-0000-000000000046', 'A', 'Administer fresh frozen plasma alone, as this is equally rapid and effective as prothrombin complex concentrate', false, 'Ruled out because prothrombin complex concentrate provides more rapid and complete reversal than fresh frozen plasma, which requires larger volumes and acts more slowly.', 1),
('d9000000-0000-0000-0000-000000000046', 'B', 'Urgent reversal with prothrombin complex concentrate and IV vitamin K, aiming to normalise the INR as quickly as possible', true, 'Correct. Warfarin-associated intracerebral haemorrhage requires urgent reversal with prothrombin complex concentrate, providing rapid replacement of vitamin K-dependent clotting factors, plus IV vitamin K to sustain reversal, aiming to normalise INR as fast as possible to limit haematoma expansion.', 2),
('d9000000-0000-0000-0000-000000000046', 'C', 'Withhold any reversal agent and simply stop warfarin, allowing natural correction of the INR over several days', false, 'Ruled out because this approach is far too slow and unsafe given the ongoing bleeding risk in acute intracerebral haemorrhage.', 3),
('d9000000-0000-0000-0000-000000000046', 'D', 'Give vitamin K alone without prothrombin complex concentrate, as this is sufficient for immediate reversal', false, 'Ruled out because vitamin K alone acts too slowly for the acute setting and must be combined with prothrombin complex concentrate for rapid reversal.', 4),
('d9000000-0000-0000-0000-000000000046', 'E', 'Administer idarucizumab, as this is the appropriate reversal agent for warfarin-associated intracerebral haemorrhage', false, 'Ruled out because idarucizumab is a reversal agent specific to dabigatran, not warfarin.', 5),
('d9000000-0000-0000-0000-000000000047', 'A', 'Withhold anticoagulation entirely because of the haemorrhagic component, and manage with antiepileptic and supportive therapy alone', false, 'Ruled out because anticoagulation remains standard of care for cerebral venous sinus thrombosis unless a specific major contraindication exists, such as a massive haemorrhage requiring surgery.', 1),
('d9000000-0000-0000-0000-000000000047', 'B', 'Give antiplatelet therapy with aspirin instead of anticoagulation, as this is safer in the context of haemorrhage', false, 'Ruled out because aspirin is not the recommended treatment for cerebral venous sinus thrombosis; anticoagulation is standard.', 2),
('d9000000-0000-0000-0000-000000000047', 'C', 'Start therapeutic anticoagulation, such as low molecular weight heparin transitioning to a longer-term agent, as this remains indicated even in the presence of an associated haemorrhagic venous infarct', true, 'Correct. Anticoagulation is the standard treatment for cerebral venous sinus thrombosis, and the presence of an associated haemorrhagic venous infarct is not, in itself, a contraindication, since most such haemorrhages do not expand with anticoagulation and untreated thrombus propagation carries a greater risk.', 3),
('d9000000-0000-0000-0000-000000000047', 'D', 'Perform urgent surgical evacuation of the haemorrhage as the primary treatment, with no role for anticoagulation', false, 'Ruled out because surgery is reserved for specific complications such as large mass effect, not as first-line management, and anticoagulation should still be given.', 4),
('d9000000-0000-0000-0000-000000000047', 'E', 'Delay any anticoagulation for at least 2 weeks to allow the haemorrhage to stabilise before treatment', false, 'Ruled out because delaying anticoagulation risks propagation of the thrombus and clinical deterioration.', 5),
('d9000000-0000-0000-0000-000000000048', 'A', 'Delay endarterectomy for at least 6 weeks to allow full neurological stabilisation before intervention', false, 'Ruled out because the benefit of endarterectomy is greatest with early surgery, particularly within 2 weeks; delaying intervention increases the cumulative risk of a further, potentially disabling stroke.', 1),
('d9000000-0000-0000-0000-000000000048', 'B', 'Endarterectomy is not indicated, as this is an asymptomatic finding since the symptoms have resolved', false, 'Ruled out because this is classified as a symptomatic stenosis, given the recent attributable TIA, which strongly favours intervention regardless of symptom resolution.', 2),
('d9000000-0000-0000-0000-000000000048', 'C', 'Endarterectomy should never be performed within the first month due to peri-operative stroke risk, regardless of degree of stenosis', false, 'Ruled out because evidence supports early rather than delayed timing given the high early recurrence risk after a symptomatic event.', 3),
('d9000000-0000-0000-0000-000000000048', 'D', 'Carotid endarterectomy should be performed as soon as possible, ideally within 2 weeks of symptom onset', true, 'Correct. Carotid endarterectomy for symptomatic significant carotid stenosis provides the greatest benefit when performed early, ideally within 2 weeks of the presenting TIA or minor stroke, given the high risk of early recurrent stroke.', 4),
('d9000000-0000-0000-0000-000000000048', 'E', 'Only carotid stenting, never endarterectomy, is appropriate this early after symptom onset', false, 'Ruled out because endarterectomy remains a suitable, standard option for early intervention after a symptomatic event; this is not a strict early-stenting-only distinction.', 5),
('d9000000-0000-0000-0000-000000000049', 'A', 'Arrange prolonged cardiac rhythm monitoring, such as extended ambulatory monitoring or an implantable loop recorder, to look for paroxysmal atrial fibrillation, which would change management to anticoagulation', true, 'Correct. Paroxysmal atrial fibrillation is a significant, frequently occult cause of cryptogenic stroke and can be missed by brief monitoring; prolonged monitoring substantially increases detection rates, and detecting atrial fibrillation would change secondary prevention from antiplatelet to anticoagulant therapy.', 1),
('d9000000-0000-0000-0000-000000000049', 'B', 'No further investigation is required, as 24-hour ECG monitoring is sufficient to exclude atrial fibrillation as a cause', false, 'Ruled out because paroxysmal atrial fibrillation is frequently missed by short-duration monitoring such as a 24-hour ECG.', 2),
('d9000000-0000-0000-0000-000000000049', 'C', 'Start empirical anticoagulation for presumed atrial fibrillation without any further monitoring', false, 'Ruled out because starting anticoagulation without a confirmed indication carries unproven benefit and unnecessary bleeding risk.', 3),
('d9000000-0000-0000-0000-000000000049', 'D', 'Add a second antiplatelet agent long-term, that is, indefinite dual antiplatelet therapy, as the most appropriate strategy for cryptogenic stroke', false, 'Ruled out because long-term dual antiplatelet therapy is not standard secondary prevention for cryptogenic stroke and increases bleeding risk without proven benefit in this context.', 4),
('d9000000-0000-0000-0000-000000000049', 'E', 'Perform routine PFO closure regardless of further workup, as this is the most common cause of cryptogenic stroke', false, 'Ruled out because PFO closure requires specific patient selection criteria, including age, high-risk PFO features, and exclusion of other causes such as atrial fibrillation, rather than routine application.', 5),
('d9000000-0000-0000-0000-000000000050', 'A', 'Stop nimodipine immediately, as it is no longer of any benefit once vasospasm develops', false, 'Ruled out because nimodipine is continued for its recommended course regardless of vasospasm development, as its benefit is largely neuroprotective rather than solely due to angiographic vasodilation.', 1),
('d9000000-0000-0000-0000-000000000050', 'B', 'Induce therapeutic hypotension to reduce the risk of rebleeding, accepting worsened cerebral perfusion', false, 'Ruled out because hypotension would worsen ischaemia in this context; the priority now is maintaining or augmenting cerebral perfusion.', 2),
('d9000000-0000-0000-0000-000000000050', 'C', 'Manage with strict fluid restriction to prevent cerebral oedema', false, 'Ruled out because hypovolaemia worsens delayed cerebral ischaemia; euvolaemia or permissive hypervolaemia strategies are preferred over fluid restriction.', 3),
('d9000000-0000-0000-0000-000000000050', 'D', 'Reassure and observe only, as delayed cerebral ischaemia typically resolves spontaneously without intervention', false, 'Ruled out because delayed cerebral ischaemia can cause permanent infarction and mandates active intervention rather than watchful waiting.', 4),
('d9000000-0000-0000-0000-000000000050', 'E', 'Optimise blood pressure and volume status to augment cerebral perfusion, using induced hypertension and euvolaemia, and consider urgent CT or catheter angiography with a view to endovascular intervention such as balloon angioplasty or intra-arterial vasodilators if severe vasospasm is confirmed', true, 'Correct. Delayed cerebral ischaemia related to vasospasm is managed by optimising cerebral perfusion, avoiding hypovolaemia/hypotension and sometimes inducing hypertension, and if this fails or vasospasm is severe on imaging, endovascular rescue therapy such as angioplasty or intra-arterial vasodilators.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('d9000000-0000-0000-0000-000000000001', 'Dexamethasone reduces mortality and neurological sequelae in pneumococcal meningitis specifically when administered with or before the first dose of antibiotics; give it empirically while awaiting organism identification.', 1),
('d9000000-0000-0000-0000-000000000001', 'Starting dexamethasone only after antibiotics have already been given negates most of the benefit and should be avoided.', 2),
('d9000000-0000-0000-0000-000000000001', 'Antibiotics (and adjunctive dexamethasone) should not be delayed for neuroimaging in suspected bacterial meningitis in the absence of specific contraindications to lumbar puncture.', 3),
('d9000000-0000-0000-0000-000000000002', 'A relapsing neurological/psychiatric illness with orofacial dyskinesias weeks after treated HSV encephalitis, with a negative repeat HSV PCR, is characteristic of post-HSV anti-NMDA receptor encephalitis.', 1),
('d9000000-0000-0000-0000-000000000002', 'This occurs in a meaningful minority of HSV encephalitis survivors (especially children and young adults) and requires CSF/serum NMDAR antibody testing and immunotherapy (steroids, IVIG/plasma exchange, or rituximab) rather than further antivirals.', 2),
('d9000000-0000-0000-0000-000000000002', 'Recognising this entity avoids inappropriately prolonged or repeated antiviral courses when the underlying process is autoimmune rather than infectious.', 3),
('d9000000-0000-0000-0000-000000000003', 'Paradoxical worsening of TB lesions or neurological signs after starting ART in TB meningitis, despite adequate anti-tuberculous treatment, suggests TB-associated immune reconstitution inflammatory syndrome (IRIS).', 1),
('d9000000-0000-0000-0000-000000000003', 'Management of TB-IRIS is corticosteroids (continuing or escalating), while continuing effective anti-tuberculous therapy and ART rather than stopping either.', 2),
('d9000000-0000-0000-0000-000000000003', 'CNS TB-IRIS can be life-threatening due to mass effect or hydrocephalus and needs prompt recognition, distinguished from drug resistance or treatment failure by its timing (after ART initiation) and clinical/radiological pattern.', 3),
('d9000000-0000-0000-0000-000000000004', 'Raised intracranial pressure is a major cause of morbidity and mortality in cryptococcal meningitis and is managed with therapeutic serial lumbar punctures rather than acetazolamide, which is not recommended.', 1),
('d9000000-0000-0000-0000-000000000004', 'ART initiation should be deferred for approximately 4-6 weeks after starting antifungal treatment in HIV-associated cryptococcal meningitis to reduce the risk of cryptococcal IRIS.', 2),
('d9000000-0000-0000-0000-000000000004', 'Persistently elevated opening pressure or hydrocephalus unresponsive to repeated lumbar punctures may require a CSF diversion procedure, but this is not the first step.', 3),
('d9000000-0000-0000-0000-000000000005', 'Listeria monocytogenes is an important cause of bacterial meningitis in older, pregnant, or immunosuppressed patients and is intrinsically resistant to cephalosporins, which are otherwise standard empirical CNS cover.', 1),
('d9000000-0000-0000-0000-000000000005', 'Empirical regimens for suspected bacterial meningitis in at-risk groups should add ampicillin or amoxicillin to cover Listeria, alongside gentamicin for synergy.', 2),
('d9000000-0000-0000-0000-000000000005', 'Co-trimoxazole is the main alternative for treating Listeria meningitis in patients with severe penicillin allergy.', 3),
('d9000000-0000-0000-0000-000000000006', 'Bacterial brain abscess management combines source control (aspiration or excision) with prolonged antibiotic therapy, typically 4-6 weeks IV, guided by organism and clinical/radiological response.', 1),
('d9000000-0000-0000-0000-000000000006', 'Serial imaging is used to monitor resolution and guide decisions about duration of treatment and transition to oral therapy, rather than treating on a fixed short course.', 2),
('d9000000-0000-0000-0000-000000000006', 'Sinugenic abscesses are often polymicrobial (anaerobes and streptococci), and empirical antibiotic choice should be broad initially, then tailored to culture and sensitivity results.', 3),
('d9000000-0000-0000-0000-000000000007', 'Seizures are the most common presentation of parenchymal neurocysticercosis, and antiepileptic therapy is a mainstay regardless of the decision about antiparasitic treatment.', 1),
('d9000000-0000-0000-0000-000000000007', 'Antiparasitic treatment (albendazole, sometimes with praziquantel) can trigger an inflammatory reaction as cysts die, worsening oedema and seizures; corticosteroids are given alongside to mitigate this.', 2),
('d9000000-0000-0000-0000-000000000007', 'Treatment decisions depend on the number, location and stage of the cysts: for example, calcified lesions generally do not need antiparasitic treatment, while intraventricular or giant cysts may need surgery.', 3),
('d9000000-0000-0000-0000-000000000008', 'Status epilepticus unresponsive to an adequate benzodiazepine dose plus a second-line IV antiepileptic (levetiracetam, valproate or phenytoin) is refractory status epilepticus, requiring escalation to general anaesthesia with continuous EEG monitoring in ICU.', 1),
('d9000000-0000-0000-0000-000000000008', 'Delaying escalation increases the risk of neuronal injury, systemic complications and worse long-term outcomes; time-based algorithms guide stepwise escalation.', 2),
('d9000000-0000-0000-0000-000000000008', 'Continuous EEG is essential once anaesthetic agents are used, since clinical convulsive activity may stop while electrographic seizures persist (non-convulsive status).', 3),
('d9000000-0000-0000-0000-000000000009', 'Sodium valproate carries a high risk of major congenital malformations and long-term neurodevelopmental impairment in children exposed in utero, and is now restricted in women of childbearing potential unless no suitable alternative exists.', 1),
('d9000000-0000-0000-0000-000000000009', 'Any change in antiepileptic regimen should be planned and specialist-supervised well before conception, balancing seizure control against teratogenic risk, rather than abrupt discontinuation.', 2),
('d9000000-0000-0000-0000-000000000009', $x$Folic acid supplementation is recommended for women with epilepsy planning pregnancy but does not eliminate valproate's teratogenic risk.$x$, 3),
('d9000000-0000-0000-0000-000000000010', 'Drug-resistant epilepsy is defined as failure of adequate trials of two tolerated, appropriately chosen antiepileptic drug schedules (as monotherapy or in combination) to achieve sustained seizure freedom.', 1),
('d9000000-0000-0000-0000-000000000010', 'Patients with drug-resistant focal epilepsy, particularly with a clear structural lesion such as hippocampal sclerosis, should be referred for specialist pre-surgical evaluation rather than continuing to trial further drugs indefinitely.', 2),
('d9000000-0000-0000-0000-000000000010', 'Epilepsy surgery, such as temporal lobectomy, offers a significantly higher chance of seizure freedom than further medical trials in well-selected, concordant cases.', 3),
('d9000000-0000-0000-0000-000000000011', 'SUDEP risk is strongly associated with frequent, uncontrolled generalised tonic-clonic seizures, particularly nocturnal and unwitnessed ones.', 1),
('d9000000-0000-0000-0000-000000000011', 'Modifiable strategies to reduce SUDEP risk include optimising antiepileptic drug adherence and dosing, seizure detection devices, and nocturnal supervision.', 2),
('d9000000-0000-0000-0000-000000000011', 'SUDEP should be discussed sensitively with all patients with epilepsy and their carers as part of routine risk counselling, not avoided.', 3),
('d9000000-0000-0000-0000-000000000012', 'Enzyme-inducing antiepileptic drugs (carbamazepine, phenytoin, phenobarbital, and to a lesser extent topiramate and oxcarbazepine) reduce the efficacy of hormonal contraceptives that rely on hepatic metabolism.', 1),
('d9000000-0000-0000-0000-000000000012', 'Non-hormonal or hormonal methods unaffected by enzyme induction, such as the copper IUD, levonorgestrel IUS, or depot medroxyprogesterone, are preferred for women on enzyme-inducing antiepileptics.', 2),
('d9000000-0000-0000-0000-000000000012', 'The same enzyme induction reduces the efficacy of other drugs metabolised by CYP450, such as warfarin, requiring dose adjustment and monitoring.', 3),
('d9000000-0000-0000-0000-000000000013', 'Lamotrigine clearance increases substantially during pregnancy (due to hormonal induction of glucuronidation), often requiring significant dose increases to maintain seizure control.', 1),
('d9000000-0000-0000-0000-000000000013', 'Monitoring clinical response (and level monitoring where available, ideally with a pre-pregnancy baseline) guides dose titration through pregnancy, with doses often needing to be reduced again postpartum to avoid toxicity.', 2),
('d9000000-0000-0000-0000-000000000013', 'Lamotrigine is generally considered one of the lower-risk antiepileptics in pregnancy, so continuing and adjusting the dose is preferred over switching to a higher-risk agent such as valproate.', 3),
('d9000000-0000-0000-0000-000000000014', 'Persistently altered consciousness after a convulsive seizure, especially with subtle motor signs (eyelid twitching, nystagmus, facial myoclonus), should raise suspicion for non-convulsive status epilepticus.', 1),
('d9000000-0000-0000-0000-000000000014', 'EEG is essential to confirm non-convulsive status epilepticus, as clinical assessment alone is unreliable, and untreated NCSE causes ongoing neuronal injury.', 2),
('d9000000-0000-0000-0000-000000000014', 'Prompt pharmacological treatment, following a similar stepwise approach to convulsive status epilepticus, is required once NCSE is confirmed, rather than assuming a benign post-ictal state.', 3),
('d9000000-0000-0000-0000-000000000015', 'Medication overuse headache is diagnosed in patients with a pre-existing headache disorder who use acute headache medications frequently (for example opioids or combination analgesics on 10 or more days per month, or simple analgesics on 15 or more days per month) and develop increasing headache frequency.', 1),
('d9000000-0000-0000-0000-000000000015', 'Management centres on withdrawing the overused medication, which often causes transient worsening before improvement, alongside starting appropriate preventive therapy for the underlying primary headache disorder.', 2),
('d9000000-0000-0000-0000-000000000015', 'Opioid-containing analgesics carry a particularly high risk of causing medication overuse headache and should be avoided in migraine management.', 3),
('d9000000-0000-0000-0000-000000000016', 'Idiopathic intracranial hypertension is managed primarily with acetazolamide (a carbonic anhydrase inhibitor reducing CSF production), weight loss support, and regular formal visual field and papilloedema monitoring, since visual loss is the main morbidity.', 1),
('d9000000-0000-0000-0000-000000000016', 'Bariatric surgery, CSF diversion procedures such as ventriculoperitoneal shunting, or venous sinus stenting are reserved for medically refractory disease or progressive visual loss.', 2),
('d9000000-0000-0000-0000-000000000016', 'Ongoing ophthalmological monitoring is essential because visual loss in idiopathic intracranial hypertension can be insidious and is the key determinant of long-term outcome, not headache severity alone.', 3),
('d9000000-0000-0000-0000-000000000017', 'Acute cluster headache attacks are treated with high-flow oxygen and fast-acting triptan formulations (subcutaneous or intranasal), as oral triptans act too slowly for the short attack duration.', 1),
('d9000000-0000-0000-0000-000000000017', 'Verapamil is the first-line preventive agent for cluster headache, requiring ECG monitoring due to dose-dependent cardiac conduction effects (PR interval prolongation), with doses often titrated higher than in cardiology use.', 2),
('d9000000-0000-0000-0000-000000000017', 'Short courses of corticosteroids or greater occipital nerve blocks may be used for transitional/bridging prevention while preventive therapy is titrated to effect.', 3),
('d9000000-0000-0000-0000-000000000018', 'CGRP-pathway-targeted monoclonal antibodies are an option for chronic migraine prevention after inadequate response to, or intolerance of, an adequate number of standard oral preventive drug classes.', 1),
('d9000000-0000-0000-0000-000000000018', 'OnabotulinumtoxinA is another evidence-based option for chronic migraine specifically (not episodic), and can be considered alongside CGRP monoclonal antibodies in this treatment-refractory setting.', 2),
('d9000000-0000-0000-0000-000000000018', 'Medication overuse headache should always be excluded and addressed before escalating preventive therapy, but is not implicated in this patient.', 3),
('d9000000-0000-0000-0000-000000000019', 'Reversible cerebral vasoconstriction syndrome classically presents with recurrent thunderclap headaches, often triggered by exertion, Valsalva, or sexual activity, and is associated with the postpartum period and vasoactive substances.', 1),
('d9000000-0000-0000-0000-000000000019', 'Initial CT/CT angiography may be normal in reversible cerebral vasoconstriction syndrome, especially early in the course; vascular imaging (repeated or catheter angiography) showing multifocal segmental vasoconstriction confirms the diagnosis, and vasoconstrictive drugs such as triptans and ergots should be avoided.', 2),
('d9000000-0000-0000-0000-000000000019', 'Every case of thunderclap headache warrants exclusion of subarachnoid haemorrhage, but a recurrent pattern with normal initial CT/CT angiography and typical triggers points towards reversible cerebral vasoconstriction syndrome rather than aneurysmal haemorrhage.', 3),
('d9000000-0000-0000-0000-000000000020', 'Classic trigeminal neuralgia presents with brief, severe, electric shock-like unilateral facial pain triggered by light touch or chewing, typically with a normal neurological examination.', 1),
('d9000000-0000-0000-0000-000000000020', 'Bilateral involvement, sensory loss, or poor response to carbamazepine are red-flag features prompting MRI to exclude secondary causes such as multiple sclerosis or a compressive lesion/vascular loop.', 2),
('d9000000-0000-0000-0000-000000000020', 'Microvascular decompression or other surgical/ablative options are considered for refractory trigeminal neuralgia, particularly once a compressive vascular cause is identified, but only after appropriate medical therapy and imaging.', 3),
('d9000000-0000-0000-0000-000000000021', 'Giant cell arteritis with any current or recent visual symptoms (amaurosis fugax, diplopia, visual loss) constitutes a same-day ophthalmological/rheumatological emergency requiring immediate high-dose corticosteroids to prevent irreversible visual loss.', 1),
('d9000000-0000-0000-0000-000000000021', 'Temporal artery biopsy (or ultrasound where available) should be arranged urgently but must never delay steroid treatment, as biopsy changes can persist for up to 2 weeks after starting steroids.', 2),
('d9000000-0000-0000-0000-000000000021', 'Jaw claudication, scalp tenderness and markedly raised inflammatory markers in an older patient are classic features supporting a clinical diagnosis of giant cell arteritis pending histological confirmation.', 3),
('d9000000-0000-0000-0000-000000000022', $x$End-of-dose wearing-off reflects declining striatal dopamine storage capacity as Parkinson's disease progresses, and is managed by strategies that prolong dopaminergic stimulation between levodopa doses.$x$, 1),
('d9000000-0000-0000-0000-000000000022', 'COMT inhibitors (entacapone, opicapone) and MAO-B inhibitors (rasagiline, selegiline) both reduce levodopa breakdown or extend its effect and are first-line adjuncts for wearing-off.', 2),
('d9000000-0000-0000-0000-000000000022', 'Deep brain stimulation is considered for motor fluctuations or dyskinesia refractory to optimised medical therapy, not as an initial step.', 3),
('d9000000-0000-0000-0000-000000000023', $x$Impulse control disorders (pathological gambling, hypersexuality, compulsive shopping or eating) are a recognised dose-related adverse effect of dopamine agonists in Parkinson's disease, more so than with levodopa.$x$, 1),
('d9000000-0000-0000-0000-000000000023', 'Management is gradual dose reduction or withdrawal of the causative dopamine agonist, as abrupt cessation can precipitate dopamine agonist withdrawal syndrome (anxiety, dysphoria, autonomic symptoms).', 2),
('d9000000-0000-0000-0000-000000000023', 'Patients and families should be counselled about this risk before or at initiation of dopamine agonist therapy, as symptoms are often concealed due to shame.', 3),
('d9000000-0000-0000-0000-000000000024', $x$Deep brain stimulation is considered in Parkinson's disease once medically refractory motor fluctuations and/or dyskinesia significantly impair quality of life, in patients who remain levodopa-responsive without major cognitive or psychiatric contraindications.$x$, 1),
('d9000000-0000-0000-0000-000000000024', 'Amantadine, an NMDA receptor antagonist, is a recognised pharmacological option specifically for levodopa-induced dyskinesia, and its failure supports escalation to device-based therapy.', 2),
('d9000000-0000-0000-0000-000000000024', 'Careful patient selection (age, cognition, absence of significant psychiatric comorbidity, good levodopa responsiveness) is essential to maximise benefit from deep brain stimulation.', 3),
('d9000000-0000-0000-0000-000000000025', 'Progressive supranuclear palsy classically presents with early postural instability and falls (often backward), vertical supranuclear gaze palsy (especially downgaze), axial rigidity, and poor or transient response to levodopa.', 1),
('d9000000-0000-0000-0000-000000000025', $x$Poor or absent sustained levodopa response and early falls are important red flags distinguishing atypical parkinsonian syndromes from idiopathic Parkinson's disease.$x$, 2),
('d9000000-0000-0000-0000-000000000025', 'Distinguishing atypical parkinsonian syndromes (progressive supranuclear palsy, multiple system atrophy, corticobasal degeneration, dementia with Lewy bodies) relies on recognising their differing core clinical features, since neuroimaging is often only supportive rather than diagnostic early in the disease course.', 3),
('d9000000-0000-0000-0000-000000000026', $x$Essential tremor is a bilateral postural/kinetic tremor without other parkinsonian features, often transiently improved by alcohol, and does not respond to dopaminergic medication, a useful distinguishing feature from Parkinson's disease.$x$, 1),
('d9000000-0000-0000-0000-000000000026', 'First-line pharmacological treatments for essential tremor are propranolol and primidone, chosen based on comorbidities and tolerability.', 2),
('d9000000-0000-0000-0000-000000000026', 'Second-line or refractory options include other agents such as topiramate or gabapentin, botulinum toxin for focal/hand tremor, or deep brain stimulation/focused ultrasound thalamotomy for severe, disabling, treatment-resistant tremor.', 3),
('d9000000-0000-0000-0000-000000000027', $x$Wilson's disease results from impaired biliary copper excretion (ATP7B mutation), leading to copper accumulation in the liver, brain (particularly the basal ganglia) and cornea (Kayser-Fleischer rings).$x$, 1),
('d9000000-0000-0000-0000-000000000027', 'Chelating agents (penicillamine, trientine) are first-line for symptomatic disease to actively mobilise and excrete excess copper; there is a recognised risk of paradoxical neurological worsening on starting chelation, particularly with penicillamine.', 2),
('d9000000-0000-0000-0000-000000000027', 'Zinc salts reduce intestinal copper absorption and are more often used for maintenance therapy or in presymptomatic/asymptomatic patients, sometimes combined with or following chelation.', 3),
('d9000000-0000-0000-0000-000000000028', $x$VMAT2 inhibitors (tetrabenazine, or newer agents such as deutetrabenazine) reduce presynaptic dopamine release and are effective for chorea in Huntington's disease, but carry a risk of depression/suicidality requiring monitoring, particularly important given the underlying disease's psychiatric burden.$x$, 1),
('d9000000-0000-0000-0000-000000000028', 'Atypical antipsychotics (e.g. olanzapine, risperidone) are alternative options for chorea, particularly when co-existing psychiatric symptoms are prominent.', 2),
('d9000000-0000-0000-0000-000000000028', $x$Huntington's disease management is multidisciplinary, addressing motor (chorea, later rigidity/bradykinesia), cognitive, and psychiatric (depression, irritability, psychosis) domains, which evolve as the disease progresses.$x$, 3),
('d9000000-0000-0000-0000-000000000029', 'High-dose corticosteroids (IV or high-dose oral methylprednisolone) are used to hasten recovery from an acute MS relapse causing significant functional impairment, though they do not alter long-term disease trajectory.', 1),
('d9000000-0000-0000-0000-000000000029', 'Disease-modifying therapies act to reduce future relapse frequency and disability accumulation; they are not used to treat an acute relapse itself.', 2),
('d9000000-0000-0000-0000-000000000029', 'Plasma exchange is reserved for severe relapses that fail to respond adequately to corticosteroids.', 3),
('d9000000-0000-0000-0000-000000000030', 'Natalizumab is a highly effective disease-modifying therapy for active/highly active MS but carries a risk of progressive multifocal leukoencephalopathy (PML), caused by JC virus reactivation.', 1),
('d9000000-0000-0000-0000-000000000030', 'PML risk stratification depends on JC virus antibody status, duration of natalizumab treatment (particularly beyond 2 years), and prior immunosuppressant use; JC virus antibody-negative patients can still seroconvert, so periodic retesting is required.', 2),
('d9000000-0000-0000-0000-000000000030', 'Patients and clinicians must weigh the substantial efficacy benefit of natalizumab in highly active MS against evolving PML risk over time, informing decisions about continuing, switching, or extending dosing intervals.', 3),
('d9000000-0000-0000-0000-000000000031', 'Neuromyelitis optica spectrum disorder (NMOSD), typically AQP4-antibody-mediated, is a distinct disease from MS with different treatment implications: several classic MS disease-modifying therapies (interferon beta, natalizumab, fingolimod) can worsen NMOSD and should be avoided.', 1),
('d9000000-0000-0000-0000-000000000031', 'Longitudinally extensive transverse myelitis (three or more vertebral segments) and severe/bilateral optic neuritis are clinical clues favouring NMOSD over MS and should prompt AQP4 (and MOG) antibody testing.', 2),
('d9000000-0000-0000-0000-000000000031', 'B-cell depleting therapy (rituximab) and newer approved agents (eculizumab, satralizumab, inebilizumab) are used for relapse prevention in AQP4-positive NMOSD, reflecting its more antibody/complement-mediated pathophysiology.', 3),
('d9000000-0000-0000-0000-000000000032', 'Fingolimod (a sphingosine-1-phosphate receptor modulator) can cause transient bradycardia and atrioventricular conduction block, most pronounced after the first dose, necessitating first-dose cardiac monitoring in a supervised setting.', 1),
('d9000000-0000-0000-0000-000000000032', 'Baseline assessment before starting fingolimod includes ECG, and consideration of cardiac history/medications (e.g. concurrent bradycardic agents) that might increase risk.', 2),
('d9000000-0000-0000-0000-000000000032', 'Other fingolimod-specific monitoring includes macular oedema surveillance (ophthalmology review), liver function tests, and varicella zoster immunity/vaccination status before starting.', 3),
('d9000000-0000-0000-0000-000000000033', 'PML risk with natalizumab rises substantially with treatment duration beyond 2 years, positive or rising JC virus antibody index, and prior immunosuppressant use; these factors should be reassessed periodically during treatment.', 1),
('d9000000-0000-0000-0000-000000000033', 'When PML risk becomes unacceptable, switching to an alternative disease-modifying therapy is considered, balancing the risk of disease reactivation (which can be significant after stopping natalizumab, sometimes with rebound activity) against ongoing PML risk.', 2),
('d9000000-0000-0000-0000-000000000033', 'Extended interval dosing has been studied as a possible risk-mitigation strategy in some patients, but is a distinct discussion, and there is no effective prophylactic antiviral for JC virus/PML.', 3),
('d9000000-0000-0000-0000-000000000034', 'Relapse rates in MS typically decrease during pregnancy, especially the third trimester, likely due to pregnancy-associated immune tolerance, but rebound in the first 3-6 months postpartum.', 1),
('d9000000-0000-0000-0000-000000000034', $x$Decisions about continuing, stopping, or switching disease-modifying therapy around conception and pregnancy are individualised to the specific drug's safety profile and the patient's disease activity, ideally planned well in advance of conception.$x$, 2),
('d9000000-0000-0000-0000-000000000034', 'Prompt resumption of an effective disease-modifying therapy postpartum, with attention to breastfeeding compatibility where relevant, is important to mitigate the recognised postpartum relapse risk, particularly after stopping higher-efficacy therapies.', 3),
('d9000000-0000-0000-0000-000000000035', 'Secondary progressive MS with evidence of ongoing inflammatory activity (relapses, new/enhancing MRI lesions) still has treatment options with proven benefit, distinguishing it from non-active progressive disease where evidence for disease-modifying therapy is weaker.', 1),
('d9000000-0000-0000-0000-000000000035', 'Siponimod is an example of an agent with specific evidence of benefit in active secondary progressive MS.', 2),
('d9000000-0000-0000-0000-000000000035', 'Comprehensive management of progressive MS also includes symptomatic treatment and rehabilitation (physiotherapy, spasticity/bladder management), but this does not replace consideration of disease-modifying therapy where active inflammation persists.', 3),
('d9000000-0000-0000-0000-000000000036', 'Myasthenic crisis is a medical emergency defined by respiratory or severe bulbar weakness requiring or nearing ventilatory support; declining forced vital capacity is a key bedside marker of impending respiratory failure.', 1),
('d9000000-0000-0000-0000-000000000036', 'Aminoglycosides, fluoroquinolones, and certain other drugs (e.g. beta-blockers, magnesium) impair neuromuscular transmission and can precipitate or worsen myasthenic crises; they should be identified and avoided.', 2),
('d9000000-0000-0000-0000-000000000036', 'Acute treatment of myasthenic crisis is plasma exchange or IVIG, which act faster than corticosteroids, alongside ICU-level respiratory monitoring and support; corticosteroids can transiently worsen weakness in the first 1-2 weeks.', 3),
('d9000000-0000-0000-0000-000000000037', 'IVIG and plasma exchange are equally effective disease-modifying treatments for Guillain-Barre syndrome; corticosteroids have no proven benefit and are not recommended.', 1),
('d9000000-0000-0000-0000-000000000037', 'Close monitoring for respiratory failure (serial vital capacity) and autonomic dysfunction (cardiac arrhythmias, labile blood pressure, ileus) is essential, as these are major causes of morbidity/mortality in Guillain-Barre syndrome.', 2),
('d9000000-0000-0000-0000-000000000037', 'Early treatment (ideally within 2 weeks of onset, and as soon as significant/progressive weakness is identified) is more effective than delayed treatment.', 3),
('d9000000-0000-0000-0000-000000000038', 'CIDP is distinguished from Guillain-Barre syndrome by its chronic (more than 8 weeks), often relapsing-remitting or progressive course, with similar demyelinating electrophysiological features and raised CSF protein with a normal cell count (albuminocytological dissociation).', 1),
('d9000000-0000-0000-0000-000000000038', 'First-line treatments for CIDP include IVIG, corticosteroids, or plasma exchange, often requiring long-term maintenance immunotherapy given the chronic relapsing course.', 2),
('d9000000-0000-0000-0000-000000000038', 'Long-term management often needs an escalation plan, such as addition of a steroid-sparing immunosuppressant, if response to a single first-line agent is inadequate or the patient becomes treatment-dependent.', 3),
('d9000000-0000-0000-0000-000000000039', 'Non-invasive ventilation is offered for symptomatic nocturnal/early respiratory insufficiency in motor neuron disease and has demonstrated survival and quality-of-life benefits when started proactively rather than delayed until overt hypercapnic respiratory failure.', 1),
('d9000000-0000-0000-0000-000000000039', 'Gastrostomy feeding decisions in motor neuron disease should be planned proactively while the patient can still swallow safely and is not critically unwell, since deferring until severe dysphagia or respiratory compromise increases procedural risk.', 2),
('d9000000-0000-0000-0000-000000000039', 'Riluzole modestly slows disease progression and is generally continued throughout the disease course unless intolerable side effects occur or in end-stage disease, and its use does not obviate the need for proactive respiratory and nutritional planning.', 3),
('d9000000-0000-0000-0000-000000000040', 'Lambert-Eaton myasthenic syndrome results from antibodies against presynaptic voltage-gated calcium channels, most classically paraneoplastic in association with small cell lung cancer, and demonstrates an incremental response to high-frequency repetitive nerve stimulation, contrasting with the decremental response seen in myasthenia gravis.', 1),
('d9000000-0000-0000-0000-000000000040', '3,4-diaminopyridine enhances presynaptic acetylcholine release and is the mainstay symptomatic treatment, sometimes combined with pyridostigmine.', 2),
('d9000000-0000-0000-0000-000000000040', 'Treating the underlying malignancy is an important part of managing paraneoplastic Lambert-Eaton myasthenic syndrome, as tumour treatment can improve the neurological syndrome; immunotherapy such as IVIG, plasma exchange, or longer-term immunosuppression may be needed for more severe or non-paraneoplastic cases.', 3),
('d9000000-0000-0000-0000-000000000041', 'Charcot-Marie-Tooth disease is the most common inherited peripheral neuropathy; CMT type 1A (PMP22 duplication) is the most frequent subtype, producing a uniformly slowed demyelinating pattern on nerve conduction studies, distinguishing it from the multifocal/patchy slowing typical of acquired CIDP.', 1),
('d9000000-0000-0000-0000-000000000041', 'A hereditary pattern (family history, pes cavus, a long-standing/static rather than relapsing course) should prompt genetic testing rather than immunotherapy, which has no role in inherited neuropathies.', 2),
('d9000000-0000-0000-0000-000000000041', 'Management is largely supportive (physiotherapy, orthotics, foot care, genetic counselling for the patient and family), as there is no disease-modifying treatment for Charcot-Marie-Tooth disease.', 3),
('d9000000-0000-0000-0000-000000000042', 'Myotonic dystrophy carries significant anaesthetic risk, including cardiac conduction abnormalities (which may be asymptomatic yet life-threatening), respiratory muscle weakness and hypersensitivity to sedatives and opioids, and risk of a generalised myotonic reaction to depolarising muscle relaxants (suxamethonium) or neostigmine.', 1),
('d9000000-0000-0000-0000-000000000042', 'Pre-operative ECG, with a low threshold for further cardiology assessment such as Holter monitoring, is important even in asymptomatic patients, given the risk of conduction disease and sudden cardiac death.', 2),
('d9000000-0000-0000-0000-000000000042', 'Anaesthetic and perioperative planning should involve specialist input, careful drug selection, and extended post-operative respiratory monitoring given the increased risk of respiratory complications.', 3),
('d9000000-0000-0000-0000-000000000043', 'In wake-up or unknown-onset stroke, MRI showing a DWI-positive lesion without a corresponding FLAIR signal change (DWI-FLAIR mismatch) suggests the infarct is recent (typically under 4.5 hours), supporting a trial of IV thrombolysis under specific imaging-based protocols.', 1),
('d9000000-0000-0000-0000-000000000043', 'This approach extends thrombolysis eligibility to patients who would otherwise be excluded purely because the exact onset time is unknown.', 2),
('d9000000-0000-0000-0000-000000000043', 'Mechanical thrombectomy remains a separate/additional consideration when a large vessel occlusion is confirmed, and is not mutually exclusive with thrombolysis when both are indicated.', 3),
('d9000000-0000-0000-0000-000000000044', 'Mechanical thrombectomy has an extended treatment window (up to 24 hours from last known well) in carefully selected patients with large vessel occlusion and favourable perfusion imaging (small infarct core with a large volume of salvageable penumbra/mismatch).', 1),
('d9000000-0000-0000-0000-000000000044', 'This extended-window approach, established by trials such as DAWN and DEFUSE-3, allows intervention well beyond the traditional 6-hour window for many patients previously excluded solely on time grounds.', 2),
('d9000000-0000-0000-0000-000000000044', 'Patient selection for extended-window thrombectomy relies heavily on advanced perfusion/core imaging rather than time from onset alone.', 3),
('d9000000-0000-0000-0000-000000000045', 'Malignant MCA infarction with progressive oedema causing herniation carries very high mortality with medical management alone; decompressive hemicraniectomy significantly reduces mortality and can improve functional outcomes, particularly when performed within 48 hours of stroke onset.', 1),
('d9000000-0000-0000-0000-000000000045', 'Patient selection considers age (better outcomes in younger patients, though benefit demonstrated across a range), pre-stroke functional status, and clinical/radiological trajectory (declining consciousness, midline shift, herniation signs).', 2),
('d9000000-0000-0000-0000-000000000045', 'Osmotic therapy may be used as a temporising measure but is not a substitute for definitive surgical decompression in malignant MCA syndrome with herniation.', 3),
('d9000000-0000-0000-0000-000000000046', 'Warfarin-associated intracerebral haemorrhage requires urgent reversal with prothrombin complex concentrate (rapid replacement of vitamin K-dependent clotting factors) plus IV vitamin K (to sustain reversal), aiming to normalise INR as fast as possible to limit haematoma expansion.', 1),
('d9000000-0000-0000-0000-000000000046', 'Fresh frozen plasma is slower and requires larger volumes than prothrombin complex concentrate, making it a less preferred option when the latter is available.', 2),
('d9000000-0000-0000-0000-000000000046', 'Reversal agents are anticoagulant-specific: idarucizumab reverses dabigatran, andexanet alfa (or prothrombin complex concentrate) is used for factor Xa inhibitors, and prothrombin complex concentrate plus vitamin K for warfarin; using the wrong reversal agent provides no benefit.', 3),
('d9000000-0000-0000-0000-000000000047', 'Anticoagulation is the standard treatment for cerebral venous sinus thrombosis, and the presence of an associated haemorrhagic venous infarct is not, in itself, a contraindication, since most such haemorrhages do not expand with anticoagulation and untreated thrombus propagation carries a greater risk.', 1),
('d9000000-0000-0000-0000-000000000047', 'Combined oral contraceptive use is an important, common, modifiable risk factor for cerebral venous sinus thrombosis and should be stopped alongside starting treatment.', 2),
('d9000000-0000-0000-0000-000000000047', 'Decompressive surgery is reserved for cerebral venous sinus thrombosis with a large space-occupying haemorrhage or infarct causing herniation, not as routine management of haemorrhagic transformation.', 3),
('d9000000-0000-0000-0000-000000000048', 'Carotid endarterectomy for symptomatic significant (typically 50-70% or greater) carotid stenosis provides the greatest benefit when performed early, ideally within 2 weeks of the presenting TIA or minor stroke, given the high risk of early recurrent stroke.', 1),
('d9000000-0000-0000-0000-000000000048', 'A resolved TIA does not make the underlying stenosis asymptomatic; it is classified as symptomatic based on the recent attributable event, which changes management thresholds and urgency substantially compared with an incidentally found asymptomatic stenosis.', 2),
('d9000000-0000-0000-0000-000000000048', 'Delaying intervention significantly increases the cumulative risk of a further, potentially disabling stroke before surgery can be performed.', 3),
('d9000000-0000-0000-0000-000000000049', 'Paroxysmal atrial fibrillation is a significant, frequently occult cause of cryptogenic stroke and can be missed by brief (e.g. 24-hour) ECG monitoring; prolonged monitoring (extended ambulatory ECG or implantable loop recorder) substantially increases detection rates.', 1),
('d9000000-0000-0000-0000-000000000049', 'Detecting atrial fibrillation on prolonged monitoring is clinically important, as it would change secondary prevention from antiplatelet to anticoagulant therapy.', 2),
('d9000000-0000-0000-0000-000000000049', 'PFO closure may be considered in selected younger patients with cryptogenic stroke and a high-risk PFO once other causes, including atrial fibrillation, have been carefully excluded, rather than as a default step.', 3),
('d9000000-0000-0000-0000-000000000050', 'Oral nimodipine is given to all patients with aneurysmal subarachnoid haemorrhage regardless of vasospasm status, as it improves neurological outcome primarily through a neuroprotective effect rather than solely by preventing angiographic vasospasm, and should be continued for its recommended course.', 1),
('d9000000-0000-0000-0000-000000000050', 'Delayed cerebral ischaemia related to vasospasm is managed by optimising cerebral perfusion (avoiding hypovolaemia/hypotension, sometimes inducing hypertension) and, if this fails or vasospasm is severe on imaging, endovascular rescue therapy (angioplasty or intra-arterial vasodilators).', 2),
('d9000000-0000-0000-0000-000000000050', 'Delayed cerebral ischaemia is a major cause of morbidity after subarachnoid haemorrhage and requires prompt recognition and active intervention rather than watchful waiting, given the risk of permanent infarction.', 3);
